import React, { useState, useRef, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

export default function PremiumDatePicker({ value, onChange, label, max, min, className = "" }) {
  const [isOpen, setIsOpen] = useState(false);
  const [viewDate, setViewDate] = useState(() => {
    if (value) return new Date(value);
    if (max) return new Date(max);
    return new Date();
  });
  const containerRef = useRef(null);

  const selectedDate = value ? new Date(value) : null;
  const currentMonth = viewDate.getMonth();
  const currentYear = viewDate.getFullYear();

  // Reset viewDate when max changes (e.g. switches to birthday field)
  useEffect(() => {
    if (!value && max) {
      setViewDate(new Date(max));
    }
  }, [max, value]);

  // Handle click outside to close
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (containerRef.current && !containerRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getDaysInMonth = (year, month) => new Date(year, month + 1, 0).getDate();
  const getFirstDayOfMonth = (year, month) => new Date(year, month, 1).getDay();

  const handlePrevMonth = (e) => {
    e.stopPropagation();
    setViewDate(new Date(currentYear, currentMonth - 1, 1));
  };

  const handleNextMonth = (e) => {
    e.stopPropagation();
    setViewDate(new Date(currentYear, currentMonth + 1, 1));
  };

  const handleYearChange = (e) => {
    e.stopPropagation();
    setViewDate(new Date(parseInt(e.target.value), currentMonth, 1));
  };

  const selectDate = (day) => {
    const y = currentYear;
    const m = String(currentMonth + 1).padStart(2, '0');
    const d = String(day).padStart(2, '0');
    const dateStr = `${y}-${m}-${d}`;
    onChange({ target: { value: dateStr } });
    setIsOpen(false);
  };

  const days = [];
  const totalDays = getDaysInMonth(currentYear, currentMonth);
  const firstDay = getFirstDayOfMonth(currentYear, currentMonth);

  for (let i = 0; i < firstDay; i++) {
    days.push(<div key={`empty-${i}`} className="h-9 w-9" />);
  }

  for (let i = 1; i <= totalDays; i++) {
    const isSelected = selectedDate && 
                      selectedDate.getDate() === i && 
                      selectedDate.getMonth() === currentMonth && 
                      selectedDate.getFullYear() === currentYear;
    
    const isToday = new Date().getDate() === i && 
                    new Date().getMonth() === currentMonth && 
                    new Date().getFullYear() === currentYear;

    const dateStr = `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
    const isDisabled = (max && dateStr > max) || (min && dateStr < min);

    days.push(
      <button
        key={i}
        type="button"
        disabled={isDisabled}
        onClick={() => selectDate(i)}
        className={`h-9 w-9 rounded-lg text-sm font-medium transition-all flex items-center justify-center
          ${isSelected ? 'bg-blue-600 text-white shadow-lg scale-110' : 
            isDisabled ? 'text-gray-200 cursor-not-allowed' :
            isToday ? 'border-2 border-blue-500 text-blue-600' : 
            'hover:bg-blue-50 text-gray-700 hover:text-blue-600'
          }`}
      >
        {i}
      </button>
    );
  }

  const years = [];
  const limitMaxYear = max ? new Date(max).getFullYear() : currentYear + 20;
  const limitMinYear = min ? new Date(min).getFullYear() : currentYear - 80;
  
  for (let y = limitMaxYear; y >= limitMinYear; y--) {
    years.push(y);
  }

  return (
    <div className={`relative ${className}`} ref={containerRef}>
      {label && <label className="block text-sm font-medium mb-1 text-gray-700">{label}</label>}
      
      <div 
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-2 w-full border border-gray-300 rounded-xl p-2.5 bg-white cursor-pointer hover:border-blue-400 transition-all focus-within:ring-2 focus-within:ring-blue-500/20 shadow-sm"
      >
        <CalendarIcon className="h-4 w-4 text-blue-500 shrink-0" />
        <span className={value ? "text-gray-900" : "text-gray-400"}>
          {value ? new Date(value).toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' }) : 'Select Date'}
        </span>
      </div>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 10, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 10, scale: 0.95 }}
            transition={{ duration: 0.2, ease: "easeOut" }}
            className="absolute z-[100] mt-2 p-4 bg-white rounded-2xl shadow-2xl border border-gray-100 w-[320px] left-0 md:left-auto"
          >
            <div className="flex items-center justify-between mb-4">
              <div className="flex flex-col">
                <span className="text-lg font-bold text-gray-900 leading-tight">
                  {MONTHS[currentMonth]}
                </span>
                <select 
                  value={currentYear} 
                  onChange={handleYearChange}
                  className="text-sm font-medium text-gray-500 border-none p-0 bg-transparent focus:ring-0 cursor-pointer hover:text-blue-600"
                >
                  {years.map(y => <option key={y} value={y}>{y}</option>)}
                </select>
              </div>
              <div className="flex gap-1">
                <button type="button" onClick={handlePrevMonth} className="p-2 rounded-lg hover:bg-gray-100 transition-colors">
                  <ChevronLeft className="h-5 w-5 text-gray-600" />
                </button>
                <button type="button" onClick={handleNextMonth} className="p-2 rounded-lg hover:bg-gray-100 transition-colors">
                  <ChevronRight className="h-5 w-5 text-gray-600" />
                </button>
              </div>
            </div>

            <div className="grid grid-cols-7 gap-1 mb-2">
              {DAYS.map(day => (
                <div key={day} className="text-[10px] uppercase font-bold text-gray-400 text-center tracking-wider">
                  {day}
                </div>
              ))}
            </div>

            <motion.div 
              key={`${currentMonth}-${currentYear}`}
              initial={{ opacity: 0, x: 10 }}
              animate={{ opacity: 1, x: 0 }}
              className="grid grid-cols-7 gap-1"
            >
              {days}
            </motion.div>

            <div className="mt-4 pt-4 border-t border-gray-100 flex justify-between items-center">
              {(() => {
                const today = new Date();
                const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
                const isTodayDisabled = (max && todayStr > max) || (min && todayStr < min);
                
                if (isTodayDisabled) return <div />;
                
                return (
                  <button 
                    type="button"
                    onClick={() => {
                      onChange({ target: { value: todayStr } });
                      setIsOpen(false);
                    }}
                    className="text-xs font-bold text-blue-600 hover:text-blue-700"
                  >
                    Go to Today
                  </button>
                );
              })()}
              <button 
                type="button"
                onClick={() => setIsOpen(false)}
                className="text-xs font-bold text-gray-400 hover:text-gray-600"
              >
                Close
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export default function PremiumSelect({ label, value, options, onChange, placeholder = "Select", className = "" }) {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (containerRef.current && !containerRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const selectedOption = options.find(opt => 
    typeof opt === 'string' ? opt === value : opt.value === value
  );

  const displayValue = selectedOption 
    ? (typeof selectedOption === 'string' ? selectedOption : selectedOption.label)
    : placeholder;

  const handleSelect = (opt) => {
    const val = typeof opt === 'string' ? opt : opt.value;
    onChange({ target: { value: val } });
    setIsOpen(false);
  };

  return (
    <div className={`relative ${className}`} ref={containerRef}>
      {label && <label className="block text-sm font-medium mb-1 text-gray-700">{label}</label>}
      
      <div 
        onClick={() => setIsOpen(!isOpen)}
        className={`flex items-center justify-between w-full border rounded-xl p-2.5 bg-white cursor-pointer transition-all shadow-sm
          ${isOpen ? 'border-blue-500 ring-2 ring-blue-500/20' : 'border-gray-300 hover:border-blue-400'}
        `}
      >
        <span className={value ? "text-gray-900" : "text-gray-400"}>
          {displayValue}
        </span>
        <motion.div
          animate={{ rotate: isOpen ? 180 : 0 }}
          transition={{ duration: 0.2 }}
        >
          <ChevronDown className={`h-4 w-4 ${isOpen ? 'text-blue-500' : 'text-gray-400'}`} />
        </motion.div>
      </div>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 5, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 5, scale: 0.98 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="absolute z-[110] mt-2 w-full bg-white rounded-2xl shadow-2xl border border-gray-100 py-2 max-h-[250px] overflow-y-auto custom-scrollbar"
          >
            {options.map((opt, idx) => {
              const optVal = typeof opt === 'string' ? opt : opt.value;
              const optLabel = typeof opt === 'string' ? opt : opt.label;
              const isSelected = optVal === value;

              return (
                <div
                  key={idx}
                  onClick={() => handleSelect(opt)}
                  className={`px-4 py-2.5 text-sm cursor-pointer transition-colors flex items-center justify-between
                    ${isSelected ? 'bg-blue-50 text-blue-700 font-semibold' : 'text-gray-700 hover:bg-gray-50'}
                  `}
                >
                  {optLabel}
                  {isSelected && (
                    <motion.div 
                      layoutId="active-check"
                      className="h-1.5 w-1.5 rounded-full bg-blue-500"
                    />
                  )}
                </div>
              );
            })}
            {options.length === 0 && (
              <div className="px-4 py-3 text-sm text-gray-400 italic">No options available</div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getAircrafts, deleteAircraft } from "./AircraftData.jsx";
import EditAircraftModal from "./EditAircraftModal";
import StatusBadge from "./StatusBadge";
import { ArrowLeft, Edit2, Trash2, Plane, Save, Calendar, Clock, Fuel, Users } from "lucide-react";

const API_URL = import.meta.env.VITE_API_URL || "http://localhost:3000/api";

const AircraftDetailsPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [aircraft, setAircraft] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [isEditing, setIsEditing] = useState(false);

  const fetchAircraftDetails = async () => {
    try {
      setLoading(true);
      const res = await fetch(`${API_URL}/aircraft/${encodeURIComponent(id)}`);
      if (!res.ok) throw new Error("Failed to fetch aircraft details");
      const data = await res.json();
      setAircraft(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (id) fetchAircraftDetails();
  }, [id]);

  const handleDelete = async () => {
    if (window.confirm("Are you sure you want to delete this aircraft?")) {
      try {
        await deleteAircraft(id);
        navigate("/aircraft");
      } catch (e) {
        alert("Failed to delete aircraft");
      }
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-12 min-h-[50vh]">
        <svg className="animate-spin h-8 w-8 text-indigo-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      </div>
    );
  }

  if (error || !aircraft) {
    return (
      <div className="p-8 text-center text-rose-500">
        <p className="text-lg font-medium">{error || "Aircraft not found"}</p>
        <button onClick={() => navigate("/aircraft")} className="mt-4 text-indigo-600 hover:underline">
          Go back to list
        </button>
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 max-w-5xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <button
          onClick={() => navigate("/aircraft")}
          className="flex items-center gap-2 text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-white transition-colors"
        >
          <ArrowLeft size={20} />
          <span>Back to Aircraft</span>
        </button>

        <div className="flex items-center gap-3">
          <button
            onClick={() => setIsEditing(true)}
            className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 hover:bg-indigo-100 dark:bg-indigo-500/10 dark:text-indigo-400 dark:hover:bg-indigo-500/20 rounded-xl font-medium transition-colors"
          >
            <Edit2 size={18} /> Edit
          </button>
          <button
            onClick={handleDelete}
            className="flex items-center gap-2 px-4 py-2 bg-rose-50 text-rose-600 hover:bg-rose-100 dark:bg-rose-500/10 dark:text-rose-400 dark:hover:bg-rose-500/20 rounded-xl font-medium transition-colors"
          >
            <Trash2 size={18} /> Delete
          </button>
        </div>
      </div>

      {/* Main Details Card */}
      <div className="bg-white dark:bg-slate-900 rounded-3xl p-8 shadow-sm border border-slate-200/60 dark:border-slate-800">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-8 border-b border-slate-100 dark:border-slate-800">
          <div className="flex items-center gap-5">
            <div className="p-4 bg-indigo-50 dark:bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 rounded-2xl">
              <Plane size={32} />
            </div>
            <div>
              <h1 className="text-3xl font-bold text-slate-900 dark:text-white">
                {aircraft.manufacturer || "Unknown"} {aircraft.model}
              </h1>
              <p className="text-lg text-slate-500 dark:text-slate-400 mt-1 font-mono">
                Tail: {aircraft.tailNumber}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <StatusBadge status={aircraft.status} />
            <span className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
              {aircraft.availability || "Available"}
            </span>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8 py-8">
          {/* Basic Info */}
          <div>
            <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Basic Information</h3>
            <dl className="space-y-4">
              <div className="flex justify-between">
                <dt className="text-slate-500 dark:text-slate-400">ID</dt>
                <dd className="font-medium text-slate-900 dark:text-slate-200">{aircraft.id}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500 dark:text-slate-400">Aircraft Type</dt>
                <dd className="font-medium text-slate-900 dark:text-slate-200">{aircraft.type}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500 dark:text-slate-400">Manufacturer</dt>
                <dd className="font-medium text-slate-900 dark:text-slate-200">{aircraft.manufacturer || "N/A"}</dd>
              </div>
            </dl>
          </div>

          {/* Technical Specs */}
          <div>
            <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Technical Specs</h3>
            <dl className="space-y-4">
              <div className="flex justify-between items-center">
                <dt className="text-slate-500 dark:text-slate-400 flex items-center gap-2"><Users size={16} /> Capacity</dt>
                <dd className="font-medium text-slate-900 dark:text-slate-200">{aircraft.capacity} Pax</dd>
              </div>
              <div className="flex justify-between items-center">
                <dt className="text-slate-500 dark:text-slate-400 flex items-center gap-2"><Fuel size={16} /> Fuel Capacity</dt>
                <dd className="font-medium text-slate-900 dark:text-slate-200">{aircraft.fuelCapacity} L</dd>
              </div>
            </dl>
          </div>

          {/* Operational Info */}
          <div>
            <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Operational Info</h3>
            <dl className="space-y-4">
              <div className="flex justify-between items-center">
                <dt className="text-slate-500 dark:text-slate-400 flex items-center gap-2"><Clock size={16} /> Total Flight Hours</dt>
                <dd className="font-medium text-slate-900 dark:text-slate-200 font-mono">{aircraft.totalFlightHours || 0} hrs</dd>
              </div>
              <div className="flex justify-between items-center">
                <dt className="text-slate-500 dark:text-slate-400 flex items-center gap-2"><Calendar size={16} /> Last Maintenance</dt>
                <dd className="font-medium text-slate-900 dark:text-slate-200">
                  {aircraft.lastMaintenance ? new Date(aircraft.lastMaintenance).toLocaleDateString() : 'N/A'}
                </dd>
              </div>
            </dl>
          </div>

          {/* Notes */}
          <div>
            <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Notes & Remarks</h3>
            <div className="bg-slate-50 dark:bg-slate-800/50 rounded-xl p-4 min-h-[100px]">
              <p className="text-slate-600 dark:text-slate-300 whitespace-pre-wrap">
                {aircraft.notes || "No notes available for this aircraft."}
              </p>
            </div>
          </div>
        </div>
      </div>

      {isEditing && (
        <EditAircraftModal
          aircraft={aircraft}
          onClose={() => setIsEditing(false)}
          onRefresh={fetchAircraftDetails}
        />
      )}
    </div>
  );
};

export default AircraftDetailsPage;

import React, { useState, useEffect } from 'react';
import { X, BookOpen, AlertCircle, Loader2 } from 'lucide-react';

const API_BASE = 'http://localhost:3000';

const LEVELS = [
    { value: 'SPL', label: 'Student Pilot License (SPL)' },
    { value: 'PPL', label: 'Private Pilot License (PPL)' },
    { value: 'CPL', label: 'Commercial Pilot License (CPL)' },
    { value: 'ATPL', label: 'Airline Transport Pilot License (ATPL)' },
    { value: 'IR', label: 'Instrument Rating (IR)' },
    { value: 'ME', label: 'Multi-Engine Rating (ME)' },
    { value: 'CFI_FIR', label: 'Flight Instructor Rating (CFI/FIR)' },
    { value: 'TYPE_RATING', label: 'Type Rating' },
    { value: 'AIR_REG', label: 'Air Regulations' },
    { value: 'AIR_NAV', label: 'Air Navigation' },
    { value: 'AV_MET', label: 'Aviation Meteorology' },
    { value: 'TECH_GEN', label: 'Technical General' },
    { value: 'TECH_SPEC', label: 'Technical Specific' },
    { value: 'RTR_A', label: 'Radio Telephony (RTR-A)' },
    { value: 'BSC_BBA_AV', label: 'B.Sc. / BBA in Aviation Management' },
    { value: 'AME', label: 'Aircraft Maintenance Engineering (AME)' },
    { value: 'GH_CC', label: 'Ground Handling & Cabin Crew Training' },
];

const Field = ({ label, required, children, hint }) => (
    <div>
        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1.5">
            {label} {required && <span className="text-red-500">*</span>}
        </label>
        {children}
        {hint && <p className="mt-1 text-xs text-gray-400 dark:text-gray-500">{hint}</p>}
    </div>
);

const inputClass =
    'w-full px-3.5 py-2.5 rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 text-sm text-gray-900 dark:text-gray-100 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition';

export default function CourseModal({ course, onClose }) {
    const isEdit = Boolean(course);

    const [form, setForm] = useState({
        code: course?.code || '',
        name: course?.name || '',
        description: course?.description || '',
        level: course?.level || '',
        durationHours: course?.durationHours || '',
        price: course?.price || '',
        isActive: course?.isActive !== undefined ? course.isActive : true,
    });

    const [saving, setSaving] = useState(false);
    const [error, setError] = useState(null);

    const set = (key, val) => setForm(f => ({ ...f, [key]: val }));

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError(null);

        if (!form.code.trim() || !form.name.trim() || !form.level || !form.durationHours || form.price === '') {
            setError('Please fill in all required fields.');
            return;
        }

        setSaving(true);
        try {
            const url = isEdit
                ? `${API_BASE}/api/courses/${course.id}`
                : `${API_BASE}/api/courses`;
            const method = isEdit ? 'PUT' : 'POST';

            const res = await fetch(url, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    ...form,
                    durationHours: parseFloat(form.durationHours),
                    price: parseFloat(form.price),
                }),
            });

            const data = await res.json();
            if (!res.ok) throw new Error(data.error || 'Something went wrong');

            onClose(true);
        } catch (err) {
            setError(err.message);
        } finally {
            setSaving(false);
        }
    };

    // Close on backdrop click
    const handleBackdrop = (e) => {
        if (e.target === e.currentTarget) onClose(false);
    };

    return (
        <div
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4"
            onClick={handleBackdrop}
        >
            <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-lg border border-gray-200 dark:border-gray-700 overflow-hidden">
                {/* Header */}
                <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/30">
                    <div className="flex items-center gap-3">
                        <div className="p-2 rounded-xl bg-blue-100 dark:bg-blue-900/40">
                            <BookOpen className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                        </div>
                        <div>
                            <h2 className="font-bold text-gray-900 dark:text-white text-base">
                                {isEdit ? 'Edit Course' : 'Add New Course'}
                            </h2>
                            <p className="text-xs text-gray-500 dark:text-gray-400">
                                {isEdit ? `Editing: ${course.code}` : 'Fill in the course details below'}
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={() => onClose(false)}
                        id="btn-close-course-modal"
                        className="p-2 rounded-lg text-gray-400 hover:text-gray-600 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                    >
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6 space-y-4 max-h-[70vh] overflow-y-auto custom-scrollbar">
                    {error && (
                        <div className="flex items-center gap-2 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 text-red-700 dark:text-red-400 rounded-xl px-4 py-3 text-sm">
                            <AlertCircle className="w-4 h-4 shrink-0" />
                            {error}
                        </div>
                    )}

                    <div className="grid grid-cols-2 gap-4">
                        <Field label="Course Code" required hint="e.g. PPL-001">
                            <input
                                id="course-code"
                                type="text"
                                value={form.code}
                                onChange={e => set('code', e.target.value.toUpperCase())}
                                placeholder="PPL-001"
                                maxLength={20}
                                className={inputClass}
                            />
                        </Field>
                        <Field label="Level" required>
                            <select
                                id="course-level"
                                value={form.level}
                                onChange={e => set('level', e.target.value)}
                                className={inputClass}
                            >
                                <option value="">Select level...</option>
                                {LEVELS.map(l => (
                                    <option key={l.value} value={l.value}>{l.label}</option>
                                ))}
                            </select>
                        </Field>
                    </div>

                    <Field label="Course Name" required>
                        <input
                            id="course-name"
                            type="text"
                            value={form.name}
                            onChange={e => set('name', e.target.value)}
                            placeholder="Private Pilot Licence – Basic"
                            className={inputClass}
                        />
                    </Field>

                    <Field label="Description" hint="Optional — brief overview of the course">
                        <textarea
                            id="course-description"
                            value={form.description}
                            onChange={e => set('description', e.target.value)}
                            placeholder="Provides foundational skills for student pilots..."
                            rows={3}
                            className={inputClass + ' resize-none'}
                        />
                    </Field>

                    <div className="grid grid-cols-2 gap-4">
                        <Field label="Duration (hours)" required>
                            <input
                                id="course-duration"
                                type="number"
                                min="0.5"
                                step="0.5"
                                value={form.durationHours}
                                onChange={e => set('durationHours', e.target.value)}
                                placeholder="40"
                                className={inputClass}
                            />
                        </Field>
                        <Field label="Price (INR)" required>
                            <div className="relative">
                                <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 text-sm font-medium">₹</span>
                                <input
                                    id="course-price"
                                    type="number"
                                    min="0"
                                    step="1"
                                    value={form.price}
                                    onChange={e => set('price', e.target.value)}
                                    placeholder="85000"
                                    className={inputClass + ' pl-7'}
                                />
                            </div>
                        </Field>
                    </div>

                    {isEdit && (
                        <Field label="Status">
                            <div className="flex items-center gap-3">
                                <button
                                    type="button"
                                    id="course-toggle-status"
                                    onClick={() => set('isActive', !form.isActive)}
                                    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-gray-800 ${form.isActive ? 'bg-blue-600' : 'bg-gray-300 dark:bg-gray-600'
                                        }`}
                                >
                                    <span
                                        className={`inline-block h-4 w-4 transform rounded-full bg-white shadow transition-transform ${form.isActive ? 'translate-x-6' : 'translate-x-1'
                                            }`}
                                    />
                                </button>
                                <span className="text-sm text-gray-700 dark:text-gray-300 font-medium">
                                    {form.isActive ? 'Active' : 'Inactive'}
                                </span>
                            </div>
                        </Field>
                    )}
                </form>

                {/* Footer */}
                <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-900/30">
                    <button
                        type="button"
                        onClick={() => onClose(false)}
                        className="px-4 py-2.5 rounded-xl border border-gray-200 dark:border-gray-700 text-sm font-semibold text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                    >
                        Cancel
                    </button>
                    <button
                        id="btn-save-course"
                        onClick={handleSubmit}
                        disabled={saving}
                        className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-blue-600 text-white text-sm font-semibold hover:bg-blue-700 disabled:opacity-60 disabled:cursor-not-allowed transition-colors shadow-lg shadow-blue-500/30"
                    >
                        {saving && <Loader2 className="w-4 h-4 animate-spin" />}
                        {saving ? 'Saving...' : isEdit ? 'Save Changes' : 'Create Course'}
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useCallback } from 'react';
import {
    BookOpen, Plus, Search, Filter, RefreshCw,
    Clock, IndianRupee, CheckCircle, XCircle,
    Edit2, Trash2, ChevronDown, AlertCircle, GraduationCap,
    Layers
} from 'lucide-react';
import CourseModal from '../components/CourseModal';

const API_BASE = 'http://localhost:3000';

const LEVEL_META = {
    PPL:          { label: 'PPL',           color: 'bg-sky-100 text-sky-700 dark:bg-sky-900/40 dark:text-sky-300' },
    CPL:          { label: 'CPL',           color: 'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300' },
    ATPL:         { label: 'ATPL',          color: 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300' },
    IFR:          { label: 'IFR',           color: 'bg-violet-100 text-violet-700 dark:bg-violet-900/40 dark:text-violet-300' },
    MULTI_ENGINE: { label: 'Multi-Engine',  color: 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300' },
    GROUND_SCHOOL:{ label: 'Ground School', color: 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300' },
    OTHER:        { label: 'Other',         color: 'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-300' },
};

const StatCard = ({ icon: Icon, label, value, color }) => (
    <div className="bg-white dark:bg-gray-800 rounded-2xl p-5 shadow-sm border border-gray-100 dark:border-gray-700 flex items-center gap-4">
        <div className={`p-3 rounded-xl ${color}`}>
            <Icon className="w-5 h-5" />
        </div>
        <div>
            <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">{label}</p>
            <p className="text-2xl font-extrabold text-gray-900 dark:text-white mt-0.5">{value}</p>
        </div>
    </div>
);

const SkeletonRow = () => (
    <tr className="animate-pulse">
        {[...Array(7)].map((_, i) => (
            <td key={i} className="px-4 py-4">
                <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-full" />
            </td>
        ))}
    </tr>
);

export default function CoursesListPage() {
    const [courses, setCourses] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [search, setSearch] = useState('');
    const [levelFilter, setLevelFilter] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [modalOpen, setModalOpen] = useState(false);
    const [editingCourse, setEditingCourse] = useState(null);
    const [deleteConfirm, setDeleteConfirm] = useState(null);
    const [hardDeleteConfirm, setHardDeleteConfirm] = useState(null);

    const fetchCourses = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const params = new URLSearchParams();
            if (search) params.set('search', search);
            if (levelFilter) params.set('level', levelFilter);
            if (statusFilter) params.set('active', statusFilter);

            const res = await fetch(`${API_BASE}/api/courses?${params}`);
            if (!res.ok) throw new Error('Failed to fetch courses');
            const data = await res.json();
            setCourses(data);
        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    }, [search, levelFilter, statusFilter]);

    useEffect(() => {
        const timer = setTimeout(fetchCourses, 300);
        return () => clearTimeout(timer);
    }, [fetchCourses]);

    const handleDelete = async (id) => {
        try {
            const res = await fetch(`${API_BASE}/api/courses/${id}`, { method: 'DELETE' });
            if (!res.ok) throw new Error('Failed to deactivate course');
            setDeleteConfirm(null);
            fetchCourses();
        } catch (err) {
            alert(err.message);
        }
    };

    const handleHardDelete = async (id) => {
        try {
            const res = await fetch(`${API_BASE}/api/courses/${id}/hard`, { method: 'DELETE' });
            if (!res.ok) throw new Error('Failed to permanently delete course');
            setHardDeleteConfirm(null);
            fetchCourses();
        } catch (err) {
            alert(err.message);
        }
    };

    const handleModalClose = (refreshNeeded) => {
        setModalOpen(false);
        setEditingCourse(null);
        if (refreshNeeded) fetchCourses();
    };

    const openEdit = (course) => {
        setEditingCourse(course);
        setModalOpen(true);
    };

    const activeCourses = courses.filter(c => c.isActive);
    const uniqueLevelsCount = new Set(courses.map(c => c.level)).size;
    const totalHours = courses.reduce((sum, c) => sum + c.durationHours, 0);

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        <BookOpen className="w-7 h-7 text-blue-600" />
                        Courses
                    </h1>
                    <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                        Manage all flight training courses offered by the school.
                    </p>
                </div>
                <button
                    id="btn-add-course"
                    onClick={() => { setEditingCourse(null); setModalOpen(true); }}
                    className="flex items-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-semibold hover:bg-blue-700 shadow-lg shadow-blue-500/30 transition-all hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-gray-900"
                >
                    <Plus className="w-4 h-4" />
                    Add Course
                </button>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard icon={Layers}       label="Total Courses" value={courses.length} color="bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400" />
                <StatCard icon={CheckCircle}  label="Active"        value={activeCourses.length} color="bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400" />
                <StatCard icon={GraduationCap}  label="Training Levels" value={uniqueLevelsCount} color="bg-violet-100 text-violet-600 dark:bg-violet-900/30 dark:text-violet-400" />
                <StatCard icon={Clock}        label="Total Hours"   value={totalHours.toFixed(0)} color="bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400" />
            </div>

            {/* Filters */}
            <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 p-4">
                <div className="flex flex-col sm:flex-row gap-3">
                    {/* Search */}
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                        <input
                            id="courses-search"
                            type="text"
                            placeholder="Search by name or code..."
                            value={search}
                            onChange={e => setSearch(e.target.value)}
                            className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 text-sm text-gray-900 dark:text-gray-100 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition"
                        />
                    </div>

                    {/* Level filter */}
                    <div className="relative">
                        <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                        <select
                            id="courses-filter-level"
                            value={levelFilter}
                            onChange={e => setLevelFilter(e.target.value)}
                            className="pl-9 pr-8 py-2.5 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 text-sm text-gray-700 dark:text-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer"
                        >
                            <option value="">All Levels</option>
                            {Object.entries(LEVEL_META).map(([k, v]) => (
                                <option key={k} value={k}>{v.label}</option>
                            ))}
                        </select>
                        <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                    </div>

                    {/* Status filter */}
                    <div className="relative">
                        <select
                            id="courses-filter-status"
                            value={statusFilter}
                            onChange={e => setStatusFilter(e.target.value)}
                            className="pl-4 pr-8 py-2.5 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 text-sm text-gray-700 dark:text-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer"
                        >
                            <option value="">All Status</option>
                            <option value="true">Active</option>
                            <option value="false">Inactive</option>
                        </select>
                        <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                    </div>

                    {/* Refresh */}
                    <button
                        id="btn-refresh-courses"
                        onClick={fetchCourses}
                        className="flex items-center gap-2 px-3 py-2.5 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 text-sm font-medium transition-colors"
                    >
                        <RefreshCw className="w-4 h-4" />
                        <span className="hidden sm:inline">Refresh</span>
                    </button>
                </div>
            </div>

            {/* Error */}
            {error && (
                <div className="flex items-center gap-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 text-red-700 dark:text-red-400 rounded-xl px-4 py-3 text-sm">
                    <AlertCircle className="w-4 h-4 shrink-0" />
                    {error}
                </div>
            )}

            {/* Table */}
            <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead>
                            <tr className="border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/50">
                                <th className="px-4 py-3.5 text-left text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Code</th>
                                <th className="px-4 py-3.5 text-left text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Course Name</th>
                                <th className="px-4 py-3.5 text-left text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Level</th>
                                <th className="px-4 py-3.5 text-left text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Duration</th>
                                <th className="px-4 py-3.5 text-left text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Price</th>
                                <th className="px-4 py-3.5 text-left text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Status</th>
                                <th className="px-4 py-3.5 text-right text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                            {loading ? (
                                [...Array(5)].map((_, i) => <SkeletonRow key={i} />)
                            ) : courses.length === 0 ? (
                                <tr>
                                    <td colSpan={7} className="text-center py-16">
                                        <div className="flex flex-col items-center gap-3 text-gray-400 dark:text-gray-500">
                                            <GraduationCap className="w-12 h-12 opacity-30" />
                                            <p className="font-medium">No courses found</p>
                                            <p className="text-xs">Try adjusting filters or add a new course.</p>
                                        </div>
                                    </td>
                                </tr>
                            ) : (
                                courses.map(course => (
                                    <tr
                                        key={course.id}
                                        className="hover:bg-gray-50 dark:hover:bg-gray-700/40 transition-colors group"
                                    >
                                        <td className="px-4 py-4">
                                            <span className="font-mono text-xs font-bold text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/30 px-2 py-1 rounded-md">
                                                {course.code}
                                            </span>
                                        </td>
                                        <td className="px-4 py-4">
                                            <p className="font-semibold text-gray-900 dark:text-white truncate max-w-[220px]">{course.name}</p>
                                            {course.description && (
                                                <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5 truncate max-w-[220px]">{course.description}</p>
                                            )}
                                        </td>
                                        <td className="px-4 py-4">
                                            <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-semibold ${LEVEL_META[course.level]?.color}`}>
                                                {LEVEL_META[course.level]?.label || course.level}
                                            </span>
                                        </td>
                                        <td className="px-4 py-4">
                                            <span className="flex items-center gap-1 text-gray-700 dark:text-gray-300 font-medium">
                                                <Clock className="w-3.5 h-3.5 text-gray-400" />
                                                {course.durationHours}h
                                            </span>
                                        </td>
                                        <td className="px-4 py-4 font-semibold text-gray-900 dark:text-white">
                                            ₹{Number(course.price).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                                        </td>
                                        <td className="px-4 py-4">
                                            {course.isActive ? (
                                                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400">
                                                    <CheckCircle className="w-3 h-3" /> Active
                                                </span>
                                            ) : (
                                                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400">
                                                    <XCircle className="w-3 h-3" /> Inactive
                                                </span>
                                            )}
                                        </td>
                                        <td className="px-4 py-4">
                                            <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button
                                                    id={`btn-edit-course-${course.id}`}
                                                    onClick={() => openEdit(course)}
                                                    className="p-1.5 rounded-lg text-gray-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 transition-colors"
                                                    title="Edit course"
                                                >
                                                    <Edit2 className="w-4 h-4" />
                                                </button>
                                                <button
                                                    id={`btn-delete-course-${course.id}`}
                                                    onClick={() => setDeleteConfirm(course)}
                                                    className="p-1.5 rounded-lg text-gray-400 hover:text-amber-600 hover:bg-amber-50 dark:hover:bg-amber-900/30 transition-colors"
                                                    title="Deactivate course"
                                                >
                                                    <XCircle className="w-4 h-4" />
                                                </button>
                                                <button
                                                    id={`btn-hard-delete-course-${course.id}`}
                                                    onClick={() => setHardDeleteConfirm(course)}
                                                    className="p-1.5 rounded-lg text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/30 transition-colors"
                                                    title="Delete permanently"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Footer count */}
                {!loading && courses.length > 0 && (
                    <div className="px-4 py-3 border-t border-gray-100 dark:border-gray-700 text-xs text-gray-500 dark:text-gray-400 font-medium">
                        Showing {courses.length} course{courses.length !== 1 ? 's' : ''}
                    </div>
                )}
            </div>

            {/* Add/Edit Modal */}
            {modalOpen && (
                <CourseModal
                    course={editingCourse}
                    onClose={handleModalClose}
                />
            )}

            {/* Delete Confirmation */}
            {deleteConfirm && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
                    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl p-6 max-w-sm w-full border border-gray-200 dark:border-gray-700">
                        <div className="flex items-center gap-3 mb-4">
                            <div className="p-2 rounded-xl bg-red-100 dark:bg-red-900/30">
                                <Trash2 className="w-5 h-5 text-red-600 dark:text-red-400" />
                            </div>
                            <div>
                                <h3 className="font-bold text-gray-900 dark:text-white">Deactivate Course</h3>
                                <p className="text-xs text-gray-500 dark:text-gray-400">This will mark the course as inactive</p>
                            </div>
                        </div>
                        <p className="text-sm text-gray-700 dark:text-gray-300 mb-6">
                            Are you sure you want to deactivate <strong>{deleteConfirm.name}</strong> ({deleteConfirm.code})?
                        </p>
                        <div className="flex gap-3">
                            <button
                                onClick={() => setDeleteConfirm(null)}
                                className="flex-1 px-4 py-2.5 rounded-xl border border-gray-200 dark:border-gray-700 text-sm font-semibold text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={() => handleDelete(deleteConfirm.id)}
                                className="flex-1 px-4 py-2.5 rounded-xl bg-red-600 text-white text-sm font-semibold hover:bg-red-700 transition-colors shadow-lg shadow-red-500/30"
                            >
                                Deactivate
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Hard Delete Confirmation */}
            {hardDeleteConfirm && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
                    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl p-6 max-w-sm w-full border border-gray-200 dark:border-gray-700">
                        <div className="flex items-center gap-3 mb-4">
                            <div className="p-2 rounded-xl bg-red-100 dark:bg-red-900/30">
                                <AlertCircle className="w-5 h-5 text-red-600 dark:text-red-400" />
                            </div>
                            <div>
                                <h3 className="font-bold text-gray-900 dark:text-white">Permanent Delete</h3>
                                <p className="text-xs text-gray-500 dark:text-gray-400">This action cannot be undone</p>
                            </div>
                        </div>
                        <p className="text-sm text-gray-700 dark:text-gray-300 mb-6">
                            Are you sure you want to <strong>permanently delete</strong> {hardDeleteConfirm.name} ({hardDeleteConfirm.code})? It will be removed entirely from the database.
                        </p>
                        <div className="flex gap-3">
                            <button
                                onClick={() => setHardDeleteConfirm(null)}
                                className="flex-1 px-4 py-2.5 rounded-xl border border-gray-200 dark:border-gray-700 text-sm font-semibold text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={() => handleHardDelete(hardDeleteConfirm.id)}
                                className="flex-1 px-4 py-2.5 rounded-xl bg-red-600 text-white text-sm font-semibold hover:bg-red-700 transition-colors shadow-lg shadow-red-500/30"
                            >
                                Delete
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

