import React, { useEffect, useState } from 'react';
import { FileText, Search, Plus, Trash2, Download, AlertCircle, Clock, History, File, ShieldCheck, FileSearch } from 'lucide-react';
import { useDocumentStore } from '../../../store/documentStore';
import { useDocumentCategoryStore } from '../../../store/documentCategoryStore';
import { UploadModal } from '../components/UploadModal';
import { DocumentDetailsModal } from '../components/DocumentDetailsModal';

export default function DocumentsRoot() {
    const { documents, fetchDocuments, deleteDocument, isLoading } = useDocumentStore();
    const { categories, fetchCategories } = useDocumentCategoryStore();
    const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [categoryIdFilter, setCategoryIdFilter] = useState('');
    const [selectedDocument, setSelectedDocument] = useState(null);
    const [documentToUpdate, setDocumentToUpdate] = useState(null);

    useEffect(() => {
        fetchDocuments();
        fetchCategories();
    }, [fetchDocuments, fetchCategories]);

    const filteredDocuments = documents.filter(doc => {
        const matchesSearch = doc.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                              doc.category?.name?.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesCategory = categoryIdFilter ? doc.categoryId.toString() === categoryIdFilter.toString() : true;
        return matchesSearch && matchesCategory;
    });

    const getStatusStyle = (doc) => {
        if (doc.status === 'EXPIRED') return 'bg-red-100 text-red-700 border-red-200 dark:bg-red-900/30 dark:text-red-400 dark:border-red-800/50';
        const warningDays = doc.category?.warningThresholdDays || 30;
        if (doc.expiryDate && new Date(doc.expiryDate) < new Date(Date.now() + warningDays * 24 * 60 * 60 * 1000)) {
            return 'bg-amber-100 text-amber-700 border-amber-200 dark:bg-amber-900/30 dark:text-amber-400 dark:border-amber-800/50';
        }
        return 'bg-emerald-100 text-emerald-700 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-400 dark:border-emerald-800/50';
    };

    const getStatusText = (doc) => {
        if (doc.status === 'EXPIRED') return 'Expired';
        const warningDays = doc.category?.warningThresholdDays || 30;
        if (doc.expiryDate && new Date(doc.expiryDate) < new Date(Date.now() + warningDays * 24 * 60 * 60 * 1000)) {
            return 'Expiring Soon';
        }
        return 'Valid';
    };

    const StatusIcon = ({ doc, className }) => {
        if (doc.status === 'EXPIRED') return <AlertCircle className={className} />;
        const warningDays = doc.category?.warningThresholdDays || 30;
        if (doc.expiryDate && new Date(doc.expiryDate) < new Date(Date.now() + warningDays * 24 * 60 * 60 * 1000)) {
            return <Clock className={className} />;
        }
        return <ShieldCheck className={className} />;
    };

    return (
        <div className="h-full flex flex-col space-y-6 animate-in fade-in duration-300">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-slate-900 dark:text-white">Document Library</h1>
                    <p className="text-slate-500 dark:text-slate-400 mt-1">Manage and track all organizational documents.</p>
                </div>
                <button 
                    onClick={() => {
                        setDocumentToUpdate(null);
                        setIsUploadModalOpen(true);
                    }}
                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl font-medium transition-all shadow-sm shadow-blue-600/20 active:scale-95"
                >
                    <Plus className="w-5 h-5" />
                    Upload Document
                </button>
            </div>

            {/* Controls */}
            <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col md:flex-row gap-4 transition-colors">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 dark:text-slate-500" />
                    <input 
                        type="text" 
                        placeholder="Search documents by title or category..."
                        className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all font-medium text-slate-700 dark:text-slate-200 dark:placeholder-slate-500"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
                <select 
                    className="md:w-48 px-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all font-medium text-slate-700 dark:text-slate-200"
                    value={categoryIdFilter}
                    onChange={(e) => setCategoryIdFilter(e.target.value)}
                >
                    <option value="">All Categories</option>
                    {categories.map(cat => (
                        <option key={cat.id} value={cat.id}>{cat.name}</option>
                    ))}
                </select>
            </div>

            {/* Document Grid */}
            {isLoading ? (
                <div className="flex-1 flex items-center justify-center min-h-[300px]">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                </div>
            ) : filteredDocuments.length === 0 ? (
                <div className="flex-1 flex flex-col items-center justify-center p-12 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 border-dashed text-slate-500 dark:text-slate-400 min-h-[400px] transition-colors">
                    <div className="bg-slate-50 dark:bg-slate-800/50 p-4 rounded-full mb-4">
                        <FileSearch className="w-12 h-12 text-blue-500/50" />
                    </div>
                    <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-1">No documents found</h3>
                    <p className="text-center max-w-sm mb-6">We couldn't find anything matching your criteria. Try adjusting your filters or upload a new document.</p>
                    <button 
                        onClick={() => {
                            setDocumentToUpdate(null);
                            setIsUploadModalOpen(true);
                        }}
                        className="text-blue-600 dark:text-blue-400 font-medium hover:underline flex items-center gap-2"
                    >
                        <Plus className="w-4 h-4" /> Upload your first document
                    </button>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {filteredDocuments.map(doc => {
                        const currentVersion = doc.versions?.[0] || {};
                        const fileUrl = currentVersion.fileUrl 
                            ? `${import.meta.env.VITE_API_URL?.replace('/api', '') || 'http://localhost:3000'}/uploads/${currentVersion.fileUrl}`
                            : '#';
                        
                        return (
                            <div 
                                key={doc.id} 
                                onClick={() => setSelectedDocument(doc)}
                                className="group bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl hover:shadow-xl hover:shadow-slate-200/50 dark:hover:shadow-black/50 hover:border-blue-200 dark:hover:border-blue-500/30 transition-all duration-300 flex flex-col overflow-hidden relative cursor-pointer"
                            >
                                
                                {/* Status badge */}
                                <div className={`absolute top-4 right-4 text-xs font-semibold px-2.5 py-1 rounded-full border flex items-center gap-1.5 backdrop-blur-md ${getStatusStyle(doc)}`}>
                                    <StatusIcon doc={doc} className="w-3.5 h-3.5" />
                                    {getStatusText(doc)}
                                </div>

                                <div className="p-6 pb-5 flex-1">
                                    <div className="w-12 h-12 rounded-xl bg-blue-50 dark:bg-blue-500/10 text-blue-600 dark:text-blue-400 flex items-center justify-center mb-4 group-hover:scale-110 group-hover:rotate-3 transition-transform duration-300">
                                        <FileText className="w-6 h-6" />
                                    </div>
                                    <h3 className="font-bold text-slate-900 dark:text-white text-lg mb-1 truncate" title={doc.title}>{doc.title}</h3>
                                    <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">{doc.category?.name || 'Uncategorized'}</p>
                                    
                                    <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800/60 space-y-2">
                                        <div className="flex items-center text-sm text-slate-600 dark:text-slate-400 gap-2">
                                            <History className="w-4 h-4 text-slate-400 dark:text-slate-500" />
                                            <span>Version {currentVersion.version || 1}</span>
                                            <span className="text-slate-300 dark:text-slate-700">•</span>
                                            <span className="text-xs">{currentVersion.size ? (currentVersion.size / 1024 / 1024).toFixed(2) + ' MB' : '--'}</span>
                                        </div>
                                        {doc.expiryDate && (
                                            <div className="flex items-center text-sm text-slate-600 dark:text-slate-400 gap-2">
                                                <Clock className="w-4 h-4 text-slate-400 dark:text-slate-500" />
                                                <span>Expires: {new Date(doc.expiryDate).toLocaleDateString()}</span>
                                            </div>
                                        )}
                                    </div>
                                </div>
                                
                                <div className="p-2 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/30 flex gap-2" onClick={e => e.stopPropagation()}>
                                    <a 
                                        href={fileUrl}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="flex-1 flex items-center justify-center gap-2 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800 hover:text-blue-600 dark:hover:text-blue-400 rounded-lg transition-colors border border-transparent hover:border-slate-200 dark:hover:border-slate-700"
                                    >
                                        <Download className="w-4 h-4" /> View
                                    </a>
                                    <button 
                                        onClick={() => {
                                            if(confirm('Are you sure you want to delete this document?')) {
                                                deleteDocument(doc.id);
                                            }
                                        }}
                                        className="p-2 text-slate-400 dark:text-slate-500 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                        title="Delete Document"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}

            <UploadModal 
                isOpen={isUploadModalOpen} 
                onClose={() => {
                    setIsUploadModalOpen(false);
                    setDocumentToUpdate(null);
                }} 
                existingDocument={documentToUpdate}
            />

            <DocumentDetailsModal
                isOpen={!!selectedDocument}
                onClose={() => setSelectedDocument(null)}
                document={selectedDocument}
                onUploadNewVersion={(doc) => {
                    setSelectedDocument(null);
                    setDocumentToUpdate(doc);
                    setIsUploadModalOpen(true);
                }}
            />
        </div>
    );
}

import React, { useState, useRef } from 'react';
import { Upload, X, File, Loader2, AlertTriangle, CheckCircle } from 'lucide-react';

const DOCUMENT_CATEGORIES = [
  'License',
  'Medical',
  'ID Proof',
  'Address Proof',
  'Qualification Certificate',
  'Employment Letter',
  'Background Check',
  'Contract / Offer Letter',
  'FIS Certificate',
  'Ground Instructor Certificate',
  'Other',
];

const REQUIRED_DOCS = ['License', 'Medical', 'ID Proof'];

function formatSize(bytes) {
  if (!bytes) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export function DocumentUpload({ onUpload, documents = [], onDelete, isLoading = false }) {
  const fileRef = useRef();
  const [dragging, setDragging] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('Other');
  const [selectedLabel, setSelectedLabel] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');

  // 🔹 Handle file select
  const handleFile = (file) => {
    if (!file) return;

    // File size validation (10MB)
    if (file.size > 10 * 1024 * 1024) {
      setError('File size should be less than 10MB');
      return;
    }

    setSelectedFile(file);
    setSelectedLabel(file.name.replace(/\.[^/.]+$/, ''));
    setError('');
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragging(false);
    const file = e.dataTransfer.files[0];
    handleFile(file);
  };

  // 🔹 Upload handler
  const handleUpload = async () => {
    if (!selectedFile) {
      setError('Please select a file');
      return;
    }

    setUploading(true);
    setError('');

    try {
      await onUpload(selectedFile, selectedCategory, selectedLabel);
      setSelectedFile(null);
      setSelectedLabel('');
      setSelectedCategory('Other');
    } catch (err) {
      setError(err.message);
    } finally {
      setUploading(false);
    }
  };

  // 🔥 VALIDATION FUNCTION (IMPORTANT)
  const uploadedCategories = documents ? documents.map((d) => d.category) : [];

  const validateDocuments = () => {
    if (!documents || documents.length < 3) {
      return 'Please upload at least 3 documents';
    }

    const missing = REQUIRED_DOCS.filter(
      (req) => !uploadedCategories.includes(req)
    );

    if (missing.length > 0) {
      return `Missing required documents: ${missing.join(', ')}`;
    }

    return null;
  };

  const validationError = validateDocuments();

  const isPdf = (url) => url?.toLowerCase().endsWith('.pdf');

  return (
    <div className="space-y-4">

      {/* 🔥 GLOBAL VALIDATION MESSAGE */}
      {validationError && (
        <div className="flex items-center gap-2 text-red-600 text-sm bg-red-50 border border-red-200 rounded-lg p-3">
          <AlertTriangle className="h-4 w-4" />
          {validationError}
        </div>
      )}

      {/* REQUIRED DOCS TRACKER */}
      <div className="flex flex-wrap items-center gap-2 mb-2">
        <span className="text-sm font-semibold text-gray-700 mr-1">Required:</span>
        {REQUIRED_DOCS.map(req => {
          const isUploaded = uploadedCategories.includes(req);
          return (
             <span key={req} className={`px-2.5 py-1 text-xs font-semibold rounded-full border flex items-center gap-1.5 transition-colors ${
               isUploaded ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-amber-50 text-amber-700 border-amber-200'
             }`}>
               {isUploaded ? <CheckCircle className="h-3 w-3" /> : <AlertTriangle className="h-3 w-3" />}
               {req}
             </span>
          )
        })}
      </div>

      {/* Upload Zone */}
      <div
        onDragOver={(e) => { e.preventDefault(); setDragging(true); }}
        onDragLeave={() => setDragging(false)}
        onDrop={handleDrop}
        onClick={() => fileRef.current?.click()}
        className={`relative border-2 border-dashed rounded-xl p-6 text-center cursor-pointer transition-all duration-200
          ${dragging
            ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
            : 'border-gray-200 dark:border-gray-700 hover:border-blue-400 hover:bg-gray-50 dark:hover:bg-gray-800/50'
          }`}
      >
        <input
          ref={fileRef}
          type="file"
          className="hidden"
          accept=".pdf,.jpg,.jpeg,.png,.webp"
          onChange={(e) => handleFile(e.target.files[0])}
        />
        <Upload className="mx-auto h-8 w-8 text-gray-400 mb-2" />
        <p className="text-sm font-medium text-gray-600">
          {selectedFile ? selectedFile.name : 'Drop file here or click to browse'}
        </p>
        <p className="text-xs text-gray-400 mt-1">
          PDF, JPG, PNG — max 10 MB
        </p>
      </div>

      {/* File Config */}
      {selectedFile && (
        <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 space-y-3">
          <div className="flex items-center gap-3">
            <File className="h-5 w-5 text-blue-600 shrink-0" />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium truncate">{selectedFile.name}</p>
              <p className="text-xs text-gray-500">{formatSize(selectedFile.size)}</p>
            </div>
            <button onClick={() => setSelectedFile(null)}>
              <X className="h-4 w-4" />
            </button>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="text-sm border rounded-lg px-3 py-1.5"
            >
              {DOCUMENT_CATEGORIES.map((c) => <option key={c}>{c}</option>)}
            </select>

            <input
              type="text"
              value={selectedLabel}
              onChange={(e) => setSelectedLabel(e.target.value)}
              placeholder="Label"
              className="text-sm border rounded-lg px-3 py-1.5"
            />
          </div>

          {error && (
            <div className="flex items-center gap-2 text-red-600 text-xs">
              <AlertTriangle className="h-3.5 w-3.5" /> {error}
            </div>
          )}

          <button
            onClick={handleUpload}
            disabled={uploading}
            className="w-full flex items-center justify-center gap-2 py-2 bg-blue-600 text-white text-sm font-semibold rounded-lg"
          >
            {uploading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}
            {uploading ? 'Uploading...' : 'Upload Document'}
          </button>
        </div>
      )}

      {/* Document List */}
      {documents.length > 0 && (
        <div className="space-y-2">
          {documents.map((doc) => (
            <div key={doc.id} className="flex items-center gap-3 p-3 border rounded-xl">
              <File className="h-4 w-4" />
              <div className="flex-1">
                <p className="text-sm font-semibold">{doc.label || doc.fileName}</p>
                <p className="text-xs text-gray-500">{doc.category}</p>
              </div>
              <a href={`http://localhost:3000${doc.fileUrl}`} target="_blank" rel="noreferrer">
                View
              </a>
              {onDelete && (
                <button onClick={() => onDelete(doc.id)}>
                  <X className="h-4 w-4" />
                </button>
              )}
            </div>
          ))}
        </div>
      )}

      {isLoading && (
        <div className="flex items-center gap-2 text-gray-400 text-sm">
          <Loader2 className="h-4 w-4 animate-spin" /> Loading...
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useEffect } from 'react';
import { useNavigate, useParams, Link } from 'react-router-dom';
import { AlertTriangle, Check, ChevronRight, FileText, BookOpen, Plus, Trash2, Loader2, X } from 'lucide-react';
import { instructorsService } from '../services/instructorsService';
import { DOCUMENT_SLOTS, COUNTRIES, INDIAN_STATES, NATIONALITIES, DESIGNATIONS, DEPARTMENTS, EMPLOYMENT_TYPES, AUTHORITIES, LICENSE_TYPES, RATINGS_LIST, AIRCRAFT_TYPES, SUBJECTS_LIST, MEDICAL_CLASSES, WEEKDAYS } from '../utils/formConstants';
// eslint-disable-next-line no-unused-vars
import { motion, AnimatePresence } from 'framer-motion';
import PremiumDatePicker from '../../../components/ui/PremiumDatePicker';
import PremiumSelect from '../../../components/ui/PremiumSelect';
import { ConfirmModal } from '../components/ConfirmModal';


// ✅ DOCUMENT VALIDATION (moved correctly)
const REQUIRED_DOCS = ['License', 'Medical', 'ID Proof'];
const PREMIUM_SELECT_CLASS = "w-full border border-gray-300 rounded-xl p-2.5 outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all bg-white hover:border-gray-400 cursor-pointer appearance-none bg-[url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2224%22%20height%3D%2224%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22currentColor%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolyline%20points%3D%226%209%2012%2015%2018%209%22%3E%3C%2Fpolyline%3E%3C%2Fsvg%3E')] bg-no-repeat bg-[position:right_12px_center] bg-[size:16px]";

const validateDocuments = (slotFiles, existingDocs) => {
  const uploadedCategories = [];

  Object.keys(slotFiles).forEach((key) => {
    const fileData = slotFiles[key];
    if (fileData) {
      if (Array.isArray(fileData) && fileData.length === 0) return;
      const slot = DOCUMENT_SLOTS.find(s => s.key === key);
      if (slot) uploadedCategories.push(slot.category);
    }
  });

  existingDocs.forEach(doc => uploadedCategories.push(doc.category));

  if (uploadedCategories.length < 3) {
    return 'Upload at least 3 documents';
  }

  const missing = REQUIRED_DOCS.filter(r => !uploadedCategories.includes(r));

  if (missing.length > 0) {
    return `Missing: ${missing.join(', ')}`;
  }

  // Check for duplicate files across slots
  const fileFingerprints = new Set();
  for (const key in slotFiles) {
    const files = slotFiles[key];
    if (!files) continue;
    const filesArr = Array.isArray(files) ? files : [files];
    for (const f of filesArr) {
      const fingerprint = `${f.name}-${f.size}`;
      if (fileFingerprints.has(fingerprint)) {
        return `Duplicate file detected: ${f.name}. Please upload unique documents.`;
      }
      fileFingerprints.add(fingerprint);
    }
  }

  return null;
};


// Form Steps Components

const handleChange = (e, field, formData, setFormData) => {
  let val = e.target.value;
  if (field === 'email') val = val.toLowerCase();
  if (field === 'licenseNumber' || field === 'medicalCertNumber') val = val.toUpperCase();
  setFormData({ ...formData, [field]: val });
};

const handleCheckbox = (e, field, formData, setFormData) => {
  setFormData({ ...formData, [field]: e.target.checked });
};



function MultiSelectPills({ options, selectedValues, onChange }) {
  const toggle = (val) => {
    if (selectedValues.includes(val)) {
      onChange(selectedValues.filter(v => v !== val));
    } else {
      onChange([...selectedValues, val]);
    }
  };
  return (
    <div className="flex flex-wrap gap-2">
      {options.map(opt => {
        const value = typeof opt === 'string' ? opt : opt.value;
        const label = typeof opt === 'string' ? opt : opt.label;
        const isSelected = selectedValues.includes(value);
        return (
          <button
            type="button"
            key={value}
            onClick={() => toggle(value)}
            className={`px-4 py-2 rounded-full text-sm font-semibold transition-all border outline-none ${isSelected ? 'bg-blue-600 text-white border-blue-600 shadow-md scale-105' : 'bg-white text-gray-700 border-gray-200 hover:border-blue-300 hover:bg-gray-50'
              }`}
          >
            {label}
          </button>
        )
      })}
    </div>
  )
}

export function PersonalInfo({ formData, setFormData }) {
  const [errors, setErrors] = useState({});

  const maxDob = useMemo(() => {
    const d = new Date();
    d.setFullYear(d.getFullYear() - 18);
    return d.toISOString().split('T')[0];
  }, []);

  const isIndia = formData.nationality === 'Indian' || !formData.nationality;

  const validateField = (name, value, otherPhoneVal) => {
    if (name === "email") {
      if (value && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
        return "Invalid email format";
      }
    }

    if (name === "phone" || name === "emergencyPhone") {
      if (value && !/^\d{10}$/.test(value)) {
        return "Must be exactly 10 digits";
      }
      const otherVal = otherPhoneVal !== undefined ? otherPhoneVal : (name === "phone" ? formData.emergencyPhone : formData.phone);
      if (value && value === otherVal) {
        return "Numbers cannot be the same";
      }
    }

    if (name === "pinCode" && isIndia) {
      if (value && !/^\d{6}$/.test(value)) {
        return "Pincode must be 6 digits";
      }
    }

    return "";
  };

  const handleInput = (e, field) => {
    let value = e.target.value;

    if (field === "phone" || field === "emergencyPhone" || field === "pinCode") {
      value = value.replace(/\D/g, "");
    }

    const newFormData = { ...formData, [field]: value };
    setFormData(newFormData);

    setErrors((prev) => {
      const updatedErrors = {
        ...prev,
        [field]: validateField(field, value, field === 'phone' ? formData.emergencyPhone : formData.phone)
      };

      // If we change one phone number, re-validate the other to clear/show consistency error
      if (field === "phone") {
        updatedErrors.emergencyPhone = validateField("emergencyPhone", formData.emergencyPhone, value);
      } else if (field === "emergencyPhone") {
        updatedErrors.phone = validateField("phone", formData.phone, value);
      }

      return updatedErrors;
    });
  };

  return (
    <div className="space-y-4 text-left">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

        <div>
          <label className="block text-sm font-medium mb-1">First Name *</label>
          <input
            type="text"
            className="w-full border rounded-xl p-2"
            value={formData.firstName || ''}
            onChange={(e) => handleInput(e, 'firstName')}
          />
        </div>

        <div>
          <label className="block text-sm font-medium mb-1">Last Name *</label>
          <input
            type="text"
            className="w-full border rounded-xl p-2"
            value={formData.lastName || ''}
            onChange={(e) => handleInput(e, 'lastName')}
          />
        </div>

        {/* EMAIL */}
        <div>
          <label className="block text-sm font-medium mb-1">Email *</label>
          <input
            type="email"
            className={`w-full border rounded-xl p-2 ${errors.email ? "border-red-500" : ""}`}
            value={formData.email || ''}
            onChange={(e) => handleInput(e, 'email')}
          />
          {errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}
        </div>

        <div>
          <PremiumDatePicker
            label="Date of Birth"
            max={maxDob}
            value={formData.dateOfBirth || ''}
            onChange={(e) => handleInput(e, 'dateOfBirth')}
          />
        </div>

        <PremiumSelect
          label="Gender"
          options={['Male', 'Female', 'Other']}
          value={formData.gender || ''}
          onChange={(e) => handleInput(e, 'gender')}
        />

        <PremiumSelect
          label="Nationality"
          options={NATIONALITIES}
          value={formData.nationality || ''}
          onChange={(e) => handleInput(e, 'nationality')}
        />

        {/* PHONE */}
        <div>
          <label className="block text-sm font-medium mb-1">Phone</label>
          <input
            type="text"
            maxLength={10}
            className={`w-full border rounded-xl p-2 ${errors.phone ? "border-red-500" : ""}`}
            value={formData.phone || ''}
            onChange={(e) => handleInput(e, 'phone')}
          />
          {errors.phone && <p className="text-red-500 text-xs mt-1">{errors.phone}</p>}
        </div>

        {/* EMERGENCY PHONE */}
        <div>
          <label className="block text-sm font-medium mb-1">Emergency Phone</label>
          <input
            type="text"
            maxLength={10}
            className={`w-full border rounded-xl p-2 ${errors.emergencyPhone ? "border-red-500" : ""}`}
            value={formData.emergencyPhone || ''}
            onChange={(e) => handleInput(e, 'emergencyPhone')}
          />
          {errors.emergencyPhone && <p className="text-red-500 text-xs mt-1">{errors.emergencyPhone}</p>}
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium mb-1">Address</label>
        <textarea
          className="w-full border rounded-xl p-2"
          value={formData.address || ''}
          onChange={(e) => handleInput(e, 'address')}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">

        <div>
          <label className="block text-sm font-medium mb-1">City</label>
          <input
            type="text"
            className="w-full border rounded-xl p-2"
            value={formData.city || ''}
            onChange={(e) => handleInput(e, 'city')}
          />
        </div>

        <PremiumSelect
          label="State"
          options={INDIAN_STATES}
          value={formData.state || ''}
          onChange={(e) => handleInput(e, 'state')}
        />

        {/* PINCODE */}
        <div>
          <label className="block text-sm font-medium mb-1">PIN Code</label>
          <input
            type="text"
            maxLength={6}
            className={`w-full border rounded-xl p-2 ${errors.pinCode ? "border-red-500" : ""}`}
            value={formData.pinCode || ''}
            onChange={(e) => handleInput(e, 'pinCode')}
          />
          {errors.pinCode && <p className="text-red-500 text-xs mt-1">{errors.pinCode}</p>}
        </div>

      </div>
    </div>
  );
}

