                ))}
              </div>
              <SectionCard title="Aircraft Flown" icon={PlaneTakeoff}>
                <TagList items={parseJSON(instructor.aircraftFlown)} emptyText="No aircraft recorded" />
              </SectionCard>
              <SectionCard title="Currency" icon={Calendar}>
                <InfoRow label="Last Flight Date" value={formatDate(instructor.lastFlightDate)} />
                <InfoRow label="Currency Status" value={<StatusBadge status={instructor.flightCurrencyStatus} showIcon />} />
                <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">Flight currency expires if no flight in 90 days (75 days = warning).</p>
              </SectionCard>
            </div>
          )}

          {/* GROUND QUALS TAB */}
          {activeTab === 'ground' && (
            <div className="space-y-5">
              <SectionCard title="Ground School Qualifications" icon={BookOpen}>
                <div className="space-y-4">
                  <div>
                    <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-2">Subjects Qualified to Teach</p>
                    <TagList items={parseJSON(instructor.subjectsCanTeach)} emptyText="None specified" />
                  </div>
                  <InfoRow label="FIS Standardization Date" value={formatDate(instructor.fisDate)} />
                </div>
              </SectionCard>
            </div>
          )}

          {/* SCHEDULE TAB */}
          {activeTab === 'schedule' && (
            <div className="space-y-5">
              <SectionCard title="Work Schedule" icon={Calendar}>
                <div className="mb-4">
                  <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-2">Working Days</p>
                  <div className="flex flex-wrap gap-2">
                    {['MON','TUE','WED','THU','FRI','SAT','SUN'].map((day) => {
                      const workDays = parseJSON(instructor.workDays);
                      const active = workDays.includes(day);
                      return (
                        <span key={day} className={`px-3 py-1.5 rounded-xl text-xs font-bold ${active ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-400 dark:text-gray-500'}`}>{day}</span>
                      );
                    })}
                  </div>
                </div>
                <InfoRow label="Preferred Start" value={instructor.preferredStartTime || '—'} />
                <InfoRow label="Preferred End" value={instructor.preferredEndTime || '—'} />
                <InfoRow label="Max Flight Hrs/Day" value={instructor.maxFlightHrsDay ? `${instructor.maxFlightHrsDay} hrs` : '8 hrs'} />
                <InfoRow label="Max Dual Hrs/Month" value={instructor.maxDualHrsMonth ? `${instructor.maxDualHrsMonth} hrs` : '100 hrs'} />
              </SectionCard>
              <SectionCard title="Capabilities" icon={CheckCircle}>
                {[
                  { label: 'Simulator sessions', value: instructor.canDoSim },
                  { label: 'Ground school sessions', value: instructor.canDoGround },
                  { label: 'Night flying', value: instructor.canDoNight },
                ].map(({ label, value }) => (
                  <div key={label} className="flex items-center justify-between py-2.5 border-b border-gray-50 dark:border-gray-700/50 last:border-0">
                    <span className="text-sm text-gray-600 dark:text-gray-400">{label}</span>
                    {value
                      ? <CheckCircle className="h-5 w-5 text-emerald-500" />
                      : <XCircle className="h-5 w-5 text-gray-300 dark:text-gray-600" />
                    }
                  </div>
                ))}
              </SectionCard>
            </div>
          )}

          {/* DOCUMENTS TAB */}
          {activeTab === 'documents' && (
            <DocumentUpload
              documents={documents}
              onUpload={handleUploadDoc}
              onDelete={handleDeleteDoc}
              isLoading={docsLoading}
            />
          )}

          {/* CHANGE LOG TAB */}
          {activeTab === 'log' && (
            <div className="space-y-3">
              {(instructor.changeLogs || []).length === 0 ? (
                <p className="text-sm text-gray-400 dark:text-gray-500 text-center py-12">No changes recorded yet.</p>
              ) : (
                instructor.changeLogs.map((log) => (
                  <div key={log.id} className="flex gap-4 items-start p-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl">
                    <div className="h-8 w-8 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center shrink-0">
                      <Clock className="h-3.5 w-3.5 text-blue-600 dark:text-blue-400" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm text-gray-900 dark:text-white">
                        <span className="font-semibold">{log.fieldChanged}</span> changed
                        {log.oldValue ? <> from <code className="text-xs bg-gray-200 dark:bg-gray-700 px-1 rounded">{log.oldValue}</code></> : ''}
                        {' '}to <code className="text-xs bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 px-1 rounded">{log.newValue}</code>
                      </p>
                      {log.note && <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5 italic">{log.note}</p>}
                      <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">
                        {new Date(log.changedAt).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })}
                      </p>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}

        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Search, Plus, Filter, GraduationCap, Phone, Mail,
  Eye, Trash2, RefreshCw, AlertTriangle, Loader2,
  ChevronLeft, ChevronRight, User, MoreHorizontal,
  Clock, ShieldCheck, MapPin
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { instructorsService } from '../services/instructorsService';
import { StatusBadge } from '../components/StatusBadge';
import { ConfirmModal } from '../components/ConfirmModal';
import { Breadcrumbs } from '../../../components/ui/Breadcrumbs';

const FILTER_DESIGNATIONS = [
  { value: '', label: 'All Designations' },
  { value: 'CHIEF_FLIGHT_INSTRUCTOR', label: 'Chief Flight Instructor' },
  { value: 'SENIOR_FLIGHT_INSTRUCTOR', label: 'Senior Flight Instructor' },
  { value: 'FLIGHT_INSTRUCTOR', label: 'Flight Instructor' },
  { value: 'GROUND_INSTRUCTOR', label: 'Ground Instructor' },
  { value: 'SIMULATOR_INSTRUCTOR', label: 'Simulator Instructor' },
];

function Avatar({ instructor }) {
  const initials = `${instructor.user?.firstName?.[0] || ''}${instructor.user?.lastName?.[0] || ''}`;
  const colors = ['bg-blue-500', 'bg-purple-500', 'bg-emerald-500', 'bg-amber-500', 'bg-rose-500', 'bg-indigo-500'];
  const colorIdx = (instructor.id || 0) % colors.length;

  if (instructor.profilePhotoUrl) {
    return (
      <img
        src={`http://localhost:3000${instructor.profilePhotoUrl}`}
        alt={initials}
        className="h-10 w-10 rounded-xl object-cover shadow-sm ring-2 ring-white"
        onError={(e) => { e.target.onerror = null; e.target.src = "https://ui-avatars.com/api/?name=" + initials; }}
      />
    );
  }

  return (
    <div className={`h-10 w-10 rounded-xl ${colors[colorIdx]} flex items-center justify-center text-white text-xs font-bold shadow-sm ring-2 ring-white`}>
      {initials}
    </div>
  );
}

export function InstructorList() {
  const navigate = useNavigate();
  const [instructors, setInstructors] = useState([]);
  const [pagination, setPagination] = useState({ page: 1, totalPages: 1, total: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState({ status: 'ACTIVE', designation: '', medicalStatus: '' });
  const [showFilters, setShowFilters] = useState(false);

  const [confirmModal, setConfirmModal] = useState({ open: false, id: null });

  const fetchData = async (page = 1) => {
    setLoading(true);
    setError('');
    try {
      const params = { page, limit: 15, ...filters };
      if (search) params.search = search;
      const res = await instructorsService.list(params);
      setInstructors(res.data || []);
      setPagination(res.pagination || { page: 1, totalPages: 1, total: 0 });
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => fetchData(1), 300);
    return () => clearTimeout(timer);
  }, [search, filters]);

  const handleDelete = async () => {
    const id = confirmModal.id;
    setConfirmModal({ open: false, id: null });
    try {
      await instructorsService.remove(id);
      fetchData(pagination.page);
    } catch (err) {
      setError(err.message);
    }
  };

  const stats = useMemo(() => [
    { label: 'Total Instructors', value: pagination.total || 0, icon: User, color: 'text-blue-600 dark:text-blue-400', bg: 'bg-blue-50 dark:bg-blue-900/20' },
    { label: 'Medical Expiring', value: instructors.filter(i => i.medicalStatus === 'EXPIRING_SOON').length, icon: Clock, color: 'text-amber-600 dark:text-amber-400', bg: 'bg-amber-50 dark:bg-amber-900/20' },
    { label: 'License Valid', value: instructors.filter(i => i.licenseStatus === 'VALID').length, icon: ShieldCheck, color: 'text-emerald-600 dark:text-emerald-400', bg: 'bg-emerald-50 dark:bg-emerald-900/20' },
    { label: 'On Leave', value: instructors.filter(i => i.employmentStatus === 'ON_LEAVE').length, icon: MapPin, color: 'text-gray-600 dark:text-gray-400', bg: 'bg-gray-100 dark:bg-slate-800/50' },
  ], [instructors, pagination.total]);

  return (
    <div className="space-y-6">

      <ConfirmModal
        isOpen={confirmModal.open}
        title="Deactivate Instructor?"
        message="Are you sure? This instructor will be moved to the inactive list."
        confirmLabel="Deactivate"
        onConfirm={handleDelete}
        onCancel={() => setConfirmModal({ open: false, id: null })}
      />

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, i) => (
          <motion.div
            key={i}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.1 }}
            className={`${stat.bg} p-4 rounded-2xl border border-white/50 dark:border-slate-700 shadow-sm flex items-center justify-between`}
          >
            <div>
              <p className="text-gray-500 text-sm font-medium">{stat.label}</p>
              <h3 className="text-2xl font-bold mt-1 text-gray-900">{stat.value}</h3>
            </div>
            <div className={`p-3 rounded-xl bg-white dark:bg-slate-800 shadow-sm ${stat.color}`}>
              <stat.icon className="h-6 w-6" />
            </div>
          </motion.div>
        ))}
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-3xl border border-gray-100 dark:border-slate-700 shadow-sm overflow-hidden">
        {/* Toolbar */}
        <div className="p-4 border-b border-gray-50 flex flex-col md:flex-row gap-4 items-center justify-between">
          <div className="relative w-full md:w-96">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search by name, email, or employee ID..."
              className="w-full pl-10 pr-4 py-2 bg-gray-50 dark:bg-slate-700/50 border border-transparent dark:border-slate-700 rounded-xl focus:bg-white dark:focus:bg-slate-800 focus:border-blue-500 outline-none transition-all text-sm dark:text-white"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="flex items-center gap-2 w-full md:w-auto">
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                showFilters ? 'bg-blue-50 text-blue-600' : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
              }`}
            >
              <Filter className="h-4 w-4" />
              Filters
            </button>
            <div className="h-8 w-[1px] bg-gray-200 mx-2" />
            <button
              onClick={() => {
                localStorage.removeItem('instructorFormDraft');
                navigate('/instructors/new');
              }}
              className="flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-blue-500/20 hover:scale-[1.02] transition-all active:scale-95"
            >
              <Plus className="h-4 w-4" />
              Add Instructor
            </button>
          </div>
        </div>

        {/* Active Filters */}
        <AnimatePresence>
          {showFilters && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="px-4 py-3 bg-gray-50/50 dark:bg-slate-700/30 border-b border-gray-50 dark:border-slate-700 grid grid-cols-1 sm:grid-cols-3 gap-2 overflow-hidden"
            >
              <select
                className="bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg px-3 py-1.5 text-xs outline-none focus:ring-1 focus:ring-blue-500 dark:text-white"
                value={filters.designation}
                onChange={(e) => setFilters({ ...filters, designation: e.target.value })}
              >
                {FILTER_DESIGNATIONS.map((d) => <option key={d.value} value={d.value}>{d.label}</option>)}
              </select>
              <select
                className="bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg px-3 py-1.5 text-xs outline-none focus:ring-1 focus:ring-blue-500 dark:text-white"
                value={filters.status}
                onChange={(e) => setFilters({ ...filters, status: e.target.value })}
              >
                <option value="ACTIVE">Status: Active</option>
                <option value="INACTIVE">Status: Inactive</option>
                <option value="ON_LEAVE">Status: On Leave</option>
              </select>
              <button 
                onClick={() => setFilters({ status: 'ACTIVE', designation: '', medicalStatus: '' })}
                className="text-xs text-blue-600 font-medium hover:underline text-left px-2"
              >
                Reset Filters
              </button>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Table View */}
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50/50 dark:bg-slate-700/50">
                <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Instructor</th>
                <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Designation</th>
                <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Contact</th>
                <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-center">Medical</th>
                <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                Array(5).fill(0).map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    <td className="px-6 py-4"><div className="h-10 w-10 bg-gray-100 rounded-xl" /></td>
                    <td className="px-6 py-4"><div className="h-4 bg-gray-100 rounded w-24" /></td>
                    <td className="px-6 py-4"><div className="h-4 bg-gray-100 rounded w-32" /></td>
                    <td className="px-6 py-4"><div className="h-6 bg-gray-100 rounded-full w-20 mx-auto" /></td>
                    <td className="px-6 py-4"><div className="h-8 bg-gray-100 rounded w-16 ml-auto" /></td>
                  </tr>
                ))
              ) : instructors.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-gray-400">
                    <AlertTriangle className="h-12 w-12 mx-auto mb-4 opacity-20" />
                    <p>No instructors found matching your criteria</p>
                  </td>
                </tr>
              ) : (
                instructors.map((inst) => (
                  <tr key={inst.id} className="hover:bg-gray-50/50 dark:hover:bg-slate-700/30 transition-colors group cursor-pointer" onClick={() => navigate(`/instructors/${inst.id}`)}>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-4">
                        <Avatar instructor={inst} />
                        <div>
                          <p className="font-bold text-gray-900 group-hover:text-blue-600 transition-colors">
                            {inst.user?.firstName} {inst.user?.lastName}
                          </p>
                          <p className="text-xs text-gray-500 font-medium">ID: {inst.employeeId || '--'}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <StatusBadge status={inst.designation} size="xs" />
                    </td>
                    <td className="px-6 py-4">
                      <div className="space-y-1">
                        <div className="flex items-center gap-2 text-xs text-gray-600">
                          <Phone className="h-3 w-3" /> {inst.phone || '--'}
                        </div>
                        <div className="flex items-center gap-2 text-xs text-gray-400">
                          <Mail className="h-3 w-3" /> {inst.user?.email || '--'}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <StatusBadge status={inst.medicalStatus} showIcon={true} size="xs" />
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex items-center justify-end gap-2" onClick={(e) => e.stopPropagation()}>
                        <button 
                          onClick={() => navigate(`/instructors/${inst.id}`)}
                          className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                        >
                          <Eye className="h-4 w-4" />
                        </button>
                        <button 
                          onClick={() => setConfirmModal({ open: true, id: inst.id })}
                          className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                        >
                          <Trash2 className="h-4 w-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination placeholder */}
        <div className="p-4 border-t border-gray-50 flex items-center justify-between text-xs font-medium text-gray-500">
          <p>Showing {instructors.length} of {pagination.total} results</p>
          <div className="flex gap-1">
            <button disabled={pagination.page === 1} className="p-1.5 rounded-lg border border-gray-100 hover:bg-gray-50 disabled:opacity-30">
              <ChevronLeft className="h-4 w-4" />
            </button>
            <button disabled={pagination.page === pagination.totalPages} className="p-1.5 rounded-lg border border-gray-100 hover:bg-gray-50 disabled:opacity-30">
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// T3 — InvoiceDetail ( invoiceNumber, amount, 3 statuses + react-to-print)
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useReactToPrint } from 'react-to-print';
import { ArrowLeft, Trash2, Printer, CheckCheck, AlertCircle, Clock, IndianRupee, Edit2 } from 'lucide-react';
import { useInvoices } from '../hooks/useInvoices';
import StatusBadge from './StatusBadge';
import PrintableInvoice from './PrintableInvoice';
import RecordPaymentModal from './RecordPaymentModal';

const fmt     = (val) => new Intl.NumberFormat('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(parseFloat(val) || 0);
const fmtDate = (d)   => d ? new Date(d).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
const fmtDateTime = (d) => d ? new Date(d).toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';

//  spec: PENDING ↔ PAID ↔ OVERDUE
const STATUS_ACTIONS = {
  PENDING: [
    { label: 'Record Payment', icon: IndianRupee,    id: 'RECORD_PAYMENT', color: 'bg-green-600 hover:bg-green-700 text-white' },
    { label: 'Mark as Overdue', icon: AlertCircle,  id: 'MARK_OVERDUE',   color: 'bg-red-600 hover:bg-red-700 text-white' },
  ],
  OVERDUE: [
    { label: 'Record Payment', icon: IndianRupee,    id: 'RECORD_PAYMENT', color: 'bg-green-600 hover:bg-green-700 text-white' },
    { label: 'Set Pending',     icon: Clock,        id: 'MARK_PENDING',   color: 'bg-amber-600 hover:bg-amber-700 text-white' },
  ],
  PAID: [],
};

export default function InvoiceDetail() {
  const { id }        = useParams();
  const navigate      = useNavigate();
  const printRef      = useRef();
  const { getInvoice, updateStatus, deleteInvoice, addPayment } = useInvoices();

  const [invoice,           setInvoice]           = useState(null);
  const [loading,           setLoading]           = useState(true);
  const [error,             setError]             = useState(null);
  const [actionLoading,     setActionLoading]     = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [showPaymentModal,  setShowPaymentModal]  = useState(false);
  const [successMessage,    setSuccessMessage]    = useState(null);

  const handlePrint = useReactToPrint({
    contentRef: printRef,
    documentTitle: invoice?.invoiceNumber || 'Invoice',
  });

  const fetchInvoice = async () => {
    setLoading(true);
    try {
      const data = await getInvoice(id);
      setInvoice(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchInvoice(); }, [id]);

  const handleAction = async (actionId) => {
    if (actionId === 'RECORD_PAYMENT') return setShowPaymentModal(true);
    
    // Fallback status map
    const mappedStatus = actionId === 'MARK_OVERDUE' ? 'OVERDUE' : 'PENDING';
    
    setActionLoading(true);
    try {
      await updateStatus(id, mappedStatus);
      await fetchInvoice();
      setSuccessMessage(`Invoice status updated to ${mappedStatus}`);
      setTimeout(() => setSuccessMessage(null), 3000);
    } catch (err) {
      alert(err.message);
    } finally {
      setActionLoading(false);
    }
  };

  const handleRecordPayment = async (paymentData) => {
    try {
      await addPayment(id, paymentData);
      await fetchInvoice();
      setSuccessMessage('Payment recorded successfully!');
      setTimeout(() => setSuccessMessage(null), 3000);
    } catch (err) {
      throw err;
    }
  };

  const handleDelete = async () => {
    try {
      await deleteInvoice(id);
      navigate('/invoices');
    } catch (err) {
      alert(err.message);
    }
  };

  if (loading) {
    return (
      <div className="space-y-4 animate-pulse">
        <div className="h-8 w-48 bg-gray-200 dark:bg-gray-700 rounded-lg" />
        <div className="h-96 bg-gray-200 dark:bg-gray-700 rounded-2xl" />
      </div>
    );
  }

  if (error || !invoice) {
    return (
      <div className="flex flex-col items-center justify-center h-64 gap-3 text-red-500">
        <p className="font-semibold text-lg">{error || 'Invoice not found'}</p>
        <button onClick={() => navigate('/invoices')} className="text-sm underline text-gray-500">Go back</button>
      </div>
    );
  }

  const actions   = STATUS_ACTIONS[invoice.status] || [];
  const subtotal  = invoice.items?.reduce((s, it) => s + parseFloat(it.totalPrice || 0), 0) || 0;
  const balanceDue = parseFloat(invoice.amount || 0) - parseFloat(invoice.paidAmount || 0);

  return (
    <div className="flex flex-col gap-6">

      {/* Success toast banner */}
      {successMessage && (
        <div className="flex items-center gap-2 px-4 py-3 rounded-xl bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 text-green-700 dark:text-green-400 text-sm font-semibold animate-pulse shadow-sm">
          <CheckCheck className="w-4 h-4" />
          {successMessage}
        </div>
      )}

      {/* Hidden print template */}
      <div style={{ display: 'none' }}>
        <PrintableInvoice ref={printRef} invoice={invoice} />
      </div>

      {/* Top bar */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          Invoice Details
        </h1>

        <div className="flex items-center gap-2 flex-wrap">
          {/* Print / PDF — T10 bonus */}
          <button onClick={handlePrint}
            className="flex items-center gap-2 px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-700 text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors">
            <Printer className="w-4 h-4" /> Print / PDF
          </button>

          {/* Edit Invoice — only for PENDING */}
          {invoice.status === 'PENDING' && (
            <button onClick={() => navigate(`/invoices/${invoice.id}/edit`)}
              className="flex items-center gap-2 px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-700 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors">
              <Edit2 className="w-4 h-4" /> Edit
            </button>
          )}

          {/* Delete — only for PENDING */}
          {invoice.status === 'PENDING' && (
            <button onClick={() => setShowDeleteConfirm(true)}
              className="flex items-center gap-2 px-3 py-2 rounded-lg border border-red-200 dark:border-red-800 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors">
              <Trash2 className="w-4 h-4" /> Delete
            </button>
          )}

          {/* Status transition buttons */}
          {actions.map(action => {
            const Icon = action.icon;
            return (
              <button key={action.id} onClick={() => handleAction(action.id)}
                disabled={actionLoading}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all shadow-sm disabled:opacity-60 ${action.color}`}>
                <Icon className="w-4 h-4" />
                {action.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Invoice Card */}
      <div className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-200 dark:border-gray-700 shadow-sm overflow-hidden">

        {/* Header gradient band */}
        <div className="px-6 py-5 bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-gray-800 dark:to-gray-800 border-b border-gray-100 dark:border-gray-700 flex flex-col sm:flex-row sm:items-start justify-between gap-4">
          <div>
            <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Invoice</p>
            <h2 className="text-3xl font-black font-mono text-gray-900 dark:text-white">{invoice.invoiceNumber}</h2>
            <div className="mt-3"><StatusBadge status={invoice.status} size="lg" /></div>
          </div>
          <div className="text-right space-y-1 text-sm">
            <p className="text-gray-500">Issued: <span className="font-bold text-gray-700 dark:text-gray-200">{fmtDate(invoice.issuedDate)}</span></p>
            <p className={invoice.status === 'OVERDUE' ? 'font-bold text-red-600 dark:text-red-400' : 'text-gray-500'}>
              Due: <span className="font-bold">{fmtDate(invoice.dueDate)}</span>
            </p>
            <p className="text-gray-500">Issued by: <span className="font-bold text-gray-700 dark:text-gray-200">
              {invoice.issuedBy?.firstName} {invoice.issuedBy?.lastName}
            </span></p>
          </div>
        </div>

        {/* Billed to */}
        <div className="px-6 py-5 border-b border-gray-100 dark:border-gray-700">
          <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Billed To</p>
          <p className="text-lg font-bold text-gray-900 dark:text-white">{invoice.student?.firstName} {invoice.student?.lastName}</p>
          <p className="text-sm text-gray-400">{invoice.student?.email}</p>
        </div>

        {/* Line items */}
        <div className="px-6 py-5 border-b border-gray-100 dark:border-gray-700">
          <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Line Items</p>
          {!invoice.items?.length ? (
            <p className="text-sm text-gray-400 italic">No line items.</p>
          ) : (
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-100 dark:border-gray-700 text-left">
                  {['Description', 'Qty', 'Unit Price', 'Total'].map(h => (
                    <th key={h} className={`pb-2 text-xs font-semibold text-gray-400 uppercase tracking-wider ${h !== 'Description' ? 'text-right' : ''}`}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50 dark:divide-gray-700/50">
                {invoice.items.map(item => (
                  <tr key={item.id} className="hover:bg-gray-50/50 dark:hover:bg-gray-700/20 transition-colors">
                    <td className="py-3 font-medium text-gray-700 dark:text-gray-300">{item.description}</td>
                    <td className="py-3 text-right text-gray-500">{item.quantity}</td>
                    <td className="py-3 text-right text-gray-500">₹{fmt(item.unitPrice)}</td>
                    <td className="py-3 text-right font-bold text-gray-900 dark:text-white">₹{fmt(item.totalPrice)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        {/* Payments Ledger */}
        <div className="px-6 py-5 border-b border-gray-100 dark:border-gray-700 bg-gray-50/30 dark:bg-gray-800/20">
          <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Payment History</p>
          {!invoice.payments?.length ? (
            <p className="text-sm text-gray-400 italic">No payments recorded.</p>
          ) : (
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left">
                  <th className="pb-2 text-xs font-semibold text-gray-400 uppercase tracking-wider">Date</th>
                  <th className="pb-2 text-xs font-semibold text-gray-400 uppercase tracking-wider">Method</th>
                  <th className="pb-2 text-xs font-semibold text-gray-400 uppercase tracking-wider">Reference</th>
                  <th className="pb-2 text-xs font-semibold text-gray-400 uppercase tracking-wider text-right">Amount</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700/50">
                {invoice.payments.map((pmt, i) => (
                  <tr key={i} className="hover:bg-white dark:hover:bg-gray-700/30 transition-colors">
                    <td className="py-2 text-gray-500 whitespace-nowrap">{fmtDateTime(pmt.paidAt || pmt.date || pmt.createdAt)}</td>
                    <td className="py-2 font-medium text-gray-700 dark:text-gray-300">
                      <span className="px-2 py-0.5 bg-gray-100 dark:bg-gray-700 rounded-md text-xs">{pmt.method}</span>
                    </td>
                    <td className="py-2 text-gray-500">{pmt.notes || '—'}</td>
                    <td className="py-2 text-right font-bold text-green-600 dark:text-green-400">₹{fmt(pmt.amount)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        {/* Totals */}
        <div className="px-6 py-5 flex justify-end">
          <div className="w-full max-w-xs space-y-2">
            <div className="flex justify-between text-sm text-gray-500">
              <span>Subtotal</span>
              <span className="font-semibold text-gray-700 dark:text-gray-200">₹{fmt(subtotal)}</span>
            </div>
            <div className="flex justify-between text-sm text-green-600 dark:text-green-400">
              <span>Amount Paid</span>
              <span className="font-semibold">₹{fmt(invoice.paidAmount)}</span>
            </div>
            <div className="border-t border-gray-200 dark:border-gray-700 pt-2 flex justify-between">
              <span className="font-bold text-gray-900 dark:text-white">Balance Due</span>
              <span className="font-black text-xl text-blue-600 dark:text-blue-400">₹{fmt(balanceDue)}</span>
            </div>
          </div>
        </div>

        {/* Notes */}
        {invoice.notes && (
          <div className="px-6 pb-5">
            <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Notes</p>
            <p className="text-sm text-gray-600 dark:text-gray-300 bg-gray-50 dark:bg-gray-700/50 rounded-lg p-3">{invoice.notes}</p>
          </div>
        )}
      </div>

      {/* Delete Confirm Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm">
          <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl p-6 w-full max-w-sm mx-4 border border-gray-200 dark:border-gray-700">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-2 rounded-full bg-red-100 dark:bg-red-900/30">
                <Trash2 className="w-5 h-5 text-red-600 dark:text-red-400" />
              </div>
              <h3 className="text-lg font-bold text-gray-900 dark:text-white">Delete Invoice?</h3>
            </div>
            <p className="text-sm text-gray-500 dark:text-gray-400 mb-6">
              This will permanently delete <span className="font-mono font-bold text-gray-700 dark:text-gray-200">{invoice.invoiceNumber}</span>.
            </p>
            <div className="flex gap-3">
              <button onClick={() => setShowDeleteConfirm(false)}
                className="flex-1 px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 text-sm font-medium text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors">
                Cancel
              </button>
              <button onClick={handleDelete}
                className="flex-1 px-4 py-2 rounded-lg bg-red-600 hover:bg-red-700 text-white text-sm font-semibold transition-colors shadow-sm">
                Delete
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Record Payment Modal */}
      {showPaymentModal && (
        <RecordPaymentModal 
          invoice={invoice} 
          onClose={() => setShowPaymentModal(false)}
          onSuccess={handleRecordPayment}
        />
      )}
    </div>
  );
}

// T3 — InvoiceForm component
// Create or Edit invoice with dynamic line items & Student drop-down
import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, Plus, Trash2, Save, Loader } from 'lucide-react';
import { useInvoices } from '../hooks/useInvoices';
import { Breadcrumbs } from '../../../components/ui/Breadcrumbs';

const EMPTY_ITEM = { description: '', quantity: 1, unitPrice: '' };

const fmt = (val) =>
  new Intl.NumberFormat('en-IN', { maximumFractionDigits: 2 }).format(parseFloat(val) || 0);

export default function InvoiceForm() {
  const navigate = useNavigate();
  const { id } = useParams();
  const isEdit = Boolean(id);
  const { createInvoice, getInvoice, updateInvoice } = useInvoices();

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);

  // Form state
  const [students, setStudents] = useState([]);
  const [studentId, setStudentId] = useState('');
  const [issuedById, setIssuedById] = useState('1'); // Admin default
  const [dueDate, setDueDate] = useState('');
  const [notes, setNotes] = useState('');
  const [items, setItems] = useState([{ ...EMPTY_ITEM }]);

  useEffect(() => {
    (async () => {
      try {
        const url = import.meta.env.VITE_API_URL ? `${import.meta.env.VITE_API_URL}/students` : 'http://localhost:3000/api/students';
        const res = await fetch(url);
        const data = await res.json();
        setStudents(Array.isArray(data) ? data : []);

        if (isEdit) {
          const inv = await getInvoice(id);
          setStudentId(String(inv.studentId));
          setIssuedById(String(inv.issuedById));
          setDueDate(inv.dueDate ? inv.dueDate.split('T')[0] : '');
          setNotes(inv.notes || '');
          setItems(
            inv.items.length > 0
              ? inv.items.map(it => ({
                  description: it.description,
                  quantity: it.quantity,
                  unitPrice: parseFloat(it.unitPrice),
                }))
              : [{ ...EMPTY_ITEM }]
          );
        }
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    })();
  }, [id, isEdit]);

  const updateItem = (idx, field, value) => {
    setItems(prev => prev.map((item, i) =>
      i === idx ? { ...item, [field]: value } : item
    ));
  };

  const addItem = () => setItems(prev => [...prev, { ...EMPTY_ITEM }]);
  const removeItem = (idx) => setItems(prev => prev.filter((_, i) => i !== idx));

  const lineTotal = (item) => (parseFloat(item.quantity) || 0) * (parseFloat(item.unitPrice) || 0);
  const grandTotal = items.reduce((s, item) => s + lineTotal(item), 0);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!studentId) return setError('Please select a student');
    if (items.some(it => !it.description || !it.unitPrice)) {
      return setError('All line items must have a description and unit price');
    }

    setSaving(true);
    setError(null);

    try {
      const payload = {
        studentId: parseInt(studentId),
        issuedById: parseInt(issuedById),
        dueDate: dueDate || null,
        notes: notes || null,
        items: items.map(it => ({
          description: it.description,
          quantity: parseInt(it.quantity) || 1,
          unitPrice: parseFloat(it.unitPrice) || 0,
        })),
      };

      if (isEdit) {
        // Send items along with update to the new backend endpoint
        await updateInvoice(id, payload);
      } else {
        const created = await createInvoice(payload);
        navigate(`/invoices/${created.id}`);
        return;
      }
      navigate(`/invoices/${id}`);
    } catch (err) {
      setError(err.message);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="space-y-4 animate-pulse max-w-4xl mx-auto mt-6">
        <div className="h-8 w-48 bg-gray-200 dark:bg-gray-700 rounded-lg" />
        <div className="h-96 bg-gray-200 dark:bg-gray-700 rounded-xl" />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 max-w-5xl mx-auto pb-10">
      <div className="flex items-center gap-4">
        <button
          onClick={() => navigate('/invoices')}
          className="flex items-center gap-2 text-sm text-gray-500 hover:text-blue-600 dark:text-gray-400 dark:hover:text-blue-400 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" /> Back to List
        </button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEdit ? 'Edit Invoice' : 'Create New Invoice'}
        </h1>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm p-6">
          <h2 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-5">
            Billing Details
          </h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
            
            <div className="flex flex-col gap-1.5">
              <label className="text-sm font-semibold text-gray-700 dark:text-gray-200">
                Student <span className="text-red-500">*</span>
              </label>
              <select
                value={studentId}
                onChange={e => setStudentId(e.target.value)}
                disabled={isEdit}
                className="px-4 py-2.5 rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 dark:text-gray-200 disabled:opacity-60 transition-all"
              >
                <option value="">Select a student...</option>
                {students.map(s => (
                  <option key={s.id} value={s.id}>
                    {s.firstName} {s.lastName} ({s.studentId})
                  </option>
                ))}
              </select>
              {isEdit && <p className="text-xs text-gray-400">Student cannot be changed.</p>}
            </div>

            <div className="flex flex-col gap-1.5">
              <label className="text-sm font-semibold text-gray-700 dark:text-gray-200">Due Date</label>
              <input
                type="date"
                value={dueDate}
                onChange={e => setDueDate(e.target.value)}
                className="px-4 py-2.5 rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 dark:text-gray-200 transition-all"
              />
            </div>

            <div className="flex flex-col gap-1.5 sm:col-span-2">
              <label className="text-sm font-semibold text-gray-700 dark:text-gray-200">Notes & Terms</label>
              <textarea
                rows={3}
                placeholder="E.g. Pay within 7 days..."
                value={notes}
                onChange={e => setNotes(e.target.value)}
                className="px-4 py-2.5 rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 dark:text-gray-200 resize-none transition-all"
              />
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm p-6">
          <div className="flex items-center justify-between mb-5">
            <h2 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
              Line Items
            </h2>
            <button
              type="button"
              onClick={addItem}
              className="flex items-center gap-1.5 text-sm text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 px-3 py-1.5 rounded-lg font-semibold transition-colors"
            >
              <Plus className="w-4 h-4" /> Add Item
            </button>
          </div>

          <div className="grid grid-cols-12 gap-3 mb-2 px-1">
            <span className="col-span-5 text-xs font-semibold text-gray-400 uppercase tracking-wider">Description</span>
            <span className="col-span-2 text-xs font-semibold text-gray-400 uppercase tracking-wider text-center">Qty</span>
            <span className="col-span-3 text-xs font-semibold text-gray-400 uppercase tracking-wider text-right">Unit Price</span>
            <span className="col-span-2 text-xs font-semibold text-gray-400 uppercase tracking-wider text-right pr-2">Total</span>
          </div>

          {items.map((item, idx) => (
            <div key={idx} className="grid grid-cols-12 gap-3 mb-3 items-center group">
              <div className="col-span-5">
                <input
                  type="text"
                  placeholder="e.g. Flight Training"
                  value={item.description}
                  onChange={e => updateItem(idx, 'description', e.target.value)}
                  className="w-full px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 dark:text-gray-200 transition-all"
                />
              </div>
              <div className="col-span-2">
                <input
                  type="number"
                  min="1"
                  value={item.quantity}
                  onChange={e => updateItem(idx, 'quantity', e.target.value)}
                  className="w-full px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm text-center focus:outline-none focus:ring-2 focus:ring-blue-500/30 dark:text-gray-200 transition-all"
                />
              </div>
              <div className="col-span-3">
                <input
                  type="number"
                  min="0"
                  step="0.01"
                  placeholder="0.00"
                  value={item.unitPrice}
                  onChange={e => updateItem(idx, 'unitPrice', e.target.value)}
                  className="w-full px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm text-right focus:outline-none focus:ring-2 focus:ring-blue-500/30 dark:text-gray-200 transition-all"
                />
              </div>
              <div className="col-span-2 flex items-center justify-between pl-1">
                <span className="text-sm font-semibold text-gray-700 dark:text-gray-200 text-right flex-1">
                  ₹{fmt(lineTotal(item))}
                </span>
                {items.length > 1 && (
                  <button
                    type="button"
                    onClick={() => removeItem(idx)}
                    className="ml-2 p-1.5 rounded text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                )}
              </div>
            </div>
          ))}

          <div className="border-t border-gray-100 dark:border-gray-700 mt-4 pt-4 flex justify-end">
            <div className="flex items-center gap-8">
              <span className="text-sm font-bold text-gray-500 uppercase">Grand Total</span>
              <span className="text-2xl font-black text-gray-900 dark:text-white">₹{fmt(grandTotal)}</span>
            </div>
          </div>
        </div>

        {error && (
          <div className="rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-4 text-sm text-red-700 dark:text-red-400 flex items-center gap-2">
            <span className="font-bold">Error:</span> {error}
          </div>
        )}

        <div className="flex items-center justify-end gap-3">
          <button
            type="button"
            onClick={() => navigate('/invoices')}
            className="px-6 py-2.5 rounded-lg border border-gray-200 dark:border-gray-700 text-sm font-medium text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={saving}
            className="flex items-center gap-2 px-8 py-2.5 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-sm font-bold shadow-sm shadow-blue-500/20 disabled:opacity-70 transition-all active:scale-95"
          >
            {saving && <Loader className="w-4 h-4 animate-spin" />}
            {saving ? 'Saving...' : isEdit ? 'Submit Updates' : 'Create Invoice'}
          </button>
        </div>
      </form>
    </div>
  );
}

// T3 — InvoiceList (T10-aligned)
// Financial Summary row + searchable table + Create Invoice modal trigger
// Enhanced with: Pagination, hover-reveal actions, improved empty state
// (Patterns adopted from Student module StudentsRoot)

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Plus, ChevronRight, ChevronLeft, Filter, RefreshCw, FileText, Edit2, Trash2 } from 'lucide-react';
import { useInvoices } from '../hooks/useInvoices';
import StatusBadge from './StatusBadge';
import InvoiceStats from './InvoiceStats';

// 3-status filter
const STATUS_OPTIONS = ['', 'PENDING', 'PAID', 'OVERDUE'];
const PER_PAGE = 10;

const fmt     = (val) => new Intl.NumberFormat('en-IN', { maximumFractionDigits: 2 }).format(parseFloat(val) || 0);
const fmtDate = (d)   => d ? new Date(d).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';

export default function InvoiceList() {
  const navigate = useNavigate();
  const { getInvoices, getStats, deleteInvoice } = useInvoices();

  const [invoices,     setInvoices]     = useState([]);
  const [stats,        setStats]        = useState(null);
  const [loading,      setLoading]      = useState(true);
  const [statsLoading, setStatsLoading] = useState(true);
  const [error,        setError]        = useState(null);

  // Filters
  const [search,       setSearch]       = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [fromDate,     setFromDate]     = useState('');
  const [toDate,       setToDate]       = useState('');

  // Pagination (from Student module pattern)
  const [page, setPage] = useState(1);

  const fetchData = async () => {
    setLoading(true);
    setStatsLoading(true);
    setError(null);
    try {
      const filters = {};
      if (statusFilter) filters.status   = statusFilter;
      if (fromDate)     filters.from     = fromDate;
      if (toDate)       filters.to       = toDate;

      const [data, statsData] = await Promise.all([getInvoices(filters), getStats()]);
      setInvoices(data);
      setStats(statsData);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
      setStatsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, [statusFilter, fromDate, toDate]);

  // Reset page when filters change
  useEffect(() => { setPage(1); }, [search, statusFilter, fromDate, toDate]);

  // Stat card click → filter by status
  const handleFilterByStatus = (status) => {
    setStatusFilter(status);
  };

  // Client-side search against invoiceNumber and student name/email
  const filtered = invoices.filter(inv => {
    if (!search) return true;
    const q           = search.toLowerCase();
    const studentName = `${inv.student?.firstName || ''} ${inv.student?.lastName || ''}`.toLowerCase();
    return (
      (inv.invoiceNumber || '').toLowerCase().includes(q) ||
      studentName.includes(q) ||
      (inv.student?.email || '').toLowerCase().includes(q)
    );
  });

  // Pagination calculations (from Student module)
  const totalPages = Math.max(1, Math.ceil(filtered.length / PER_PAGE));
  const first = (page - 1) * PER_PAGE;
  const last  = first + PER_PAGE;
  const paginated = filtered.slice(first, last);

  // Delete handler with confirmation
  const handleDelete = async (e, inv) => {
    e.stopPropagation();
    if (!confirm(`Delete invoice ${inv.invoiceNumber}? This cannot be undone.`)) return;
    try {
      await deleteInvoice(inv.id);
      await fetchData();
    } catch (err) {
      alert(err.message);
    }
  };

  return (
    <div className="flex flex-col h-full space-y-6">
      {/* Page Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Invoices</h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">Manage student billing and payment records</p>
        </div>
        {/* Create Invoice page navigation */}
        <button
          onClick={() => navigate('/invoices/new')}
          className="inline-flex items-center gap-2 rounded-lg bg-blue-600 hover:bg-blue-700 text-white px-4 py-2.5 text-sm font-semibold shadow-sm transition-all duration-200 hover:shadow-md active:scale-95"
        >
          <Plus className="w-4 h-4" />
          Create Invoice
        </button>
      </div>

      {/* T10 required: Financial Summary row — now with click-to-filter */}
      <InvoiceStats
        stats={stats}
        loading={statsLoading}
        activeFilter={statusFilter}
        onFilterByStatus={handleFilterByStatus}
      />

      {/* Filters Bar */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4 mb-4 flex flex-wrap gap-3 items-center shadow-sm">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Search invoice #, student name, email…"
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full pl-9 pr-4 py-2 rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 dark:text-gray-200 transition-all"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter className="w-4 h-4 text-gray-400" />
          <select
            value={statusFilter}
            onChange={e => setStatusFilter(e.target.value)}
            className="rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500/30 dark:text-gray-200 transition-all"
          >
            {STATUS_OPTIONS.map(s => (
              <option key={s} value={s}>{s || 'All Statuses'}</option>
            ))}
          </select>
        </div>

        <input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)}
          className="rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500/30 dark:text-gray-200 transition-all"
        />
        <span className="text-gray-400 text-sm">to</span>
        <input type="date" value={toDate} onChange={e => setToDate(e.target.value)}
          className="rounded-lg border border-gray-200 dark:border-gray-600 bg-gray-50 dark:bg-gray-900 text-sm px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500/30 dark:text-gray-200 transition-all"
        />

        <button onClick={fetchData}
          className="p-2 rounded-lg border border-gray-200 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors text-gray-500 dark:text-gray-400"
          title="Refresh">
          <RefreshCw className="w-4 h-4" />
        </button>
      </div>

      {/* Searchable invoice table */}
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm overflow-hidden flex-1">
        {error ? (
          <div className="flex flex-col items-center justify-center h-48 text-red-500 gap-2">
            <p className="font-semibold">{error}</p>
            <button onClick={fetchData} className="text-sm underline">Retry</button>
          </div>
        ) : loading ? (
          <div className="p-6 space-y-4">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="h-12 rounded-lg bg-gray-100 dark:bg-gray-700 animate-pulse" />
            ))}
          </div>
        ) : filtered.length === 0 ? (
          /* Enhanced empty state — pattern from Student module */
          <div className="flex flex-col items-center justify-center h-48 text-gray-400 gap-3">
            <div className="p-4 bg-gray-100 dark:bg-gray-700 rounded-full">
              <FileText className="w-8 h-8 text-gray-400" />
            </div>
            <p className="text-lg font-semibold">No invoices found</p>
            <p className="text-sm">Adjust your filters or create a new invoice.</p>
          </div>
        ) : (
          <>
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                <thead className="bg-gray-50 dark:bg-gray-900/50">
