﻿import React, { useState, useEffect } from 'react';

export default function SlotRequestsRoot() {
    const [requests, setRequests] = useState([]);
    const [filter, setFilter] = useState('All'); // All, Pending, Approved, Rejected

    useEffect(() => {
        fetchRequests();
    }, []);

    const fetchRequests = async () => {
        try {
            const response = await fetch('http://localhost:3000/api/slot-requests');
            if (response.ok) {
                const data = await response.json();
                setRequests(data);
            }
        } catch (error) {
            console.error('Error fetching slot requests:', error);
        }
    };

    const handleUpdateStatus = async (id, newStatus) => {
        try {
            const response = await fetch(`http://localhost:3000/api/slot-requests/${id}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ status: newStatus })
            });

            if (response.ok) {
                setRequests(requests.map(req => req.id === id ? { ...req, status: newStatus } : req));
            }
        } catch (error) {
            console.error("Error updating slot request status", error);
        }
    };

    const getStatusStyle = (status) => {
        switch(status) {
            case 'Approved': return 'bg-green-100 text-green-800 border-green-200 dark:bg-green-900/30 dark:text-green-400 dark:border-green-800';
            case 'Rejected': return 'bg-red-100 text-red-800 border-red-200 dark:bg-red-900/30 dark:text-red-400 dark:border-red-800';
            case 'Pending': default: return 'bg-yellow-100 text-yellow-800 border-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-400 dark:border-yellow-800';
        }
    };

    const filteredRequests = requests.filter(req => filter === 'All' ? true : req.status === filter);

    return (
        <div className="h-full flex flex-col bg-gray-50 dark:bg-gray-900 p-4 sm:p-6 rounded-xl">
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
                <div>
                    <h1 className="text-3xl font-extrabold text-gray-900 dark:text-white tracking-tight">Manage Slot Requests</h1>
                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 flex items-center">
                        <svg className="w-4 h-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                        Review and approve flight session requests submitted by students
                    </p>
                </div>

                <div className="flex bg-gray-200 dark:bg-gray-800 p-1 rounded-lg w-full md:w-auto">
                    {['All', 'Pending', 'Approved', 'Rejected'].map(status => (
                        <button 
                            key={status}
                            onClick={() => setFilter(status)} 
                            className={`flex-1 md:flex-none px-4 py-1.5 rounded-md text-sm font-semibold transition-all ${filter === status ? 'bg-white dark:bg-gray-700 shadow flex items-center justify-center text-blue-600 dark:text-blue-400' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-300 dark:hover:bg-gray-700'}`}
                        >
                            {status}
                        </button>
                    ))}
                </div>
            </div>

            {/* List Section */}
            <div className="flex-1 overflow-y-auto custom-scrollbar pr-2">
                {filteredRequests.length === 0 ? (
                    <div className="text-center py-24 bg-white dark:bg-gray-800 rounded-2xl border border-dashed border-gray-300 dark:border-gray-700">
                        <svg className="mx-auto h-12 w-12 text-gray-400 mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                        </svg>
                        <p className="text-lg font-medium text-gray-900 dark:text-white">No requests found</p>
                        <p className="text-sm mt-1 text-gray-500">There are no {filter.toLowerCase()} requests at the moment.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
                        {filteredRequests.map(req => (
                            <div key={req.id} className="relative bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-2xl p-5 shadow-sm hover:shadow-lg transition-all flex flex-col">
                                <div className="flex justify-between items-start mb-4 pb-4 border-b border-gray-100 dark:border-gray-700">
                                    <div>
                                        <h3 className="text-lg font-bold text-gray-900 dark:text-white flex items-center gap-2">
                                            <svg className="h-5 w-5 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                            {req.date}
                                        </h3>
                                        <p className="text-sm font-semibold text-gray-500 dark:text-gray-400 mt-1">
                                            {req.timePreference}
                                        </p>
                                    </div>
                                    <span className={`inline-flex items-center px-2.5 py-1 rounded-md text-xs font-bold border shadow-sm ${getStatusStyle(req.status)}`}>
                                        {req.status === 'Pending' && <span className="w-1.5 h-1.5 rounded-full bg-yellow-500 mr-1.5 animate-pulse"></span>}
                                        {req.status}
                                    </span>
                                </div>
                                
                                <div className="space-y-4 flex-1">
                                    <div className="bg-gray-50 dark:bg-gray-900/50 rounded-xl p-3">
                                        <div className="flex items-center gap-3 mb-2">
                                            <div className="h-8 w-8 rounded-full bg-blue-100 dark:bg-blue-900/50 flex flex-shrink-0 items-center justify-center text-blue-600 dark:text-blue-400 font-bold text-xs">
                                                {req.student.charAt(0)}
                                            </div>
                                            <div>
                                                <p className="text-xs text-gray-500 border-b border-transparent dark:text-gray-400 uppercase tracking-widest font-semibold">Student</p>
                                                <p className="text-sm font-bold text-gray-900 dark:text-white">{req.student}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-3 px-1 mt-3 pt-3 border-t border-gray-200 dark:border-gray-700/50">
                                            <div>
                                                <p className="text-xs text-gray-500 dark:text-gray-400 uppercase tracking-widest font-semibold">Requested Inst.</p>
                                                <p className="text-sm font-medium text-gray-800 dark:text-gray-200">{req.instructor}</p>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex flex-wrap gap-2">
                                        <span className="inline-flex items-center px-2 py-1 rounded bg-gray-100 dark:bg-gray-700 text-xs font-semibold text-gray-700 dark:text-gray-300 border border-gray-200 dark:border-gray-600 shadow-sm">
                                            <svg className="w-3.5 h-3.5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                                            {req.aircraft}
                                        </span>
                                    </div>

                                    {req.notes && (
                                        <div className="bg-yellow-50 dark:bg-yellow-900/10 p-3 rounded-lg border border-yellow-100 dark:border-yellow-900/30">
                                            <p className="text-xs text-yellow-800 dark:text-yellow-500 italic">
                                                <span className="font-bold mr-1">Note:</span>"{req.notes}"
                                            </p>
                                        </div>
                                    )}
                                </div>

                                {/* Actions */}
                                {req.status === 'Pending' && (
                                    <div className="mt-5 pt-4 border-t border-gray-100 dark:border-gray-700 grid grid-cols-2 gap-3">
                                        <button 
                                            onClick={() => handleUpdateStatus(req.id, 'Rejected')}
                                            className="w-full flex justify-center items-center py-2 px-3 border border-red-200 dark:border-red-800/50 rounded-lg shadow-sm text-sm font-bold text-red-600 dark:text-red-400 bg-white dark:bg-gray-800 hover:bg-red-50 dark:hover:bg-red-900/20 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 transition-colors"
                                        >
                                            <svg className="w-4 h-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                                            Reject
                                        </button>
                                        <button 
                                            onClick={() => handleUpdateStatus(req.id, 'Approved')}
                                            className="w-full flex justify-center items-center py-2 px-3 border border-transparent rounded-lg shadow-sm text-sm font-bold text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 transition-colors"
                                        >
                                            <svg className="w-4 h-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                                            Approve
                                        </button>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { 
  User, ShieldCheck, HeartPulse, FileText, Lock, 
  ChevronRight, ChevronLeft, Save, Plus, Trash2, CheckCircle2,
  Upload, X
} from "lucide-react";
import { useRef } from "react";


const InputField = ({ label, name, type = "text", required, fullWidth, value, onChange, options }) => (
  <div className={`space-y-1 ${fullWidth ? 'col-span-2' : ''}`}>
    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300">
      {label} {required && <span className="text-rose-500">*</span>}
    </label>
    {type === "textarea" ? (
      <textarea
        name={name}
        value={value}
        onChange={onChange}
        required={required}
        rows={3}
        className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:bg-white dark:focus:bg-slate-800 transition-colors"
      />
    ) : type === "select" ? (
      <select
        name={name}
        value={value}
        onChange={onChange}
        required={required}
        className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:bg-white dark:focus:bg-slate-800 transition-colors"
      >
        <option value="" disabled>Select an option</option>
        {options?.map((opt) => (
          <option key={opt.value} value={opt.value}>{opt.label}</option>
        ))}
      </select>
    ) : (
      <input
        type={type}
        name={name}
        value={value}
        onChange={onChange}
        required={required}
        className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:bg-white dark:focus:bg-slate-800 transition-colors"
      />
    )}
  </div>
);

export default function StudentForm() {
  const navigate = useNavigate();
  const { id } = useParams();
  const isEdit = Boolean(id);

  const [step, setStep] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [pendingFiles, setPendingFiles] = useState([]);
  const fileRef = useRef(null);
  const [dragging, setDragging] = useState(false);

  const [form, setForm] = useState({
    firstName: "", lastName: "", email: "", dob: "", gender: "", 
    nationality: "", phone: "", address: "", city: "", state: "", pincode: "",
    licenseNumber: "", licenseType: "", licenseIssueDate: "", licenseExpiryDate: "",
    medicalCertificateNumber: "", medicalIssueDate: "", medicalExpiryDate: "",
    schoolEmail: "", passwordHash: "", batch: "", documents: []
  });

  const steps = [
    { num: 1, title: "Personal Info", icon: User },
    { num: 2, title: "License", icon: ShieldCheck },
    { num: 3, title: "Medical", icon: HeartPulse },
    { num: 4, title: "Account", icon: Lock },
    { num: 5, title: "Documents", icon: FileText }
  ];

  useEffect(() => {
    if (isEdit) {
      loadStudent();
    }
  }, [id]);

  const loadStudent = async () => {
    try {
      const res = await fetch(`http://localhost:3000/api/students/${id}`);
      const data = await res.json();

      setForm(prev => ({
        ...prev,
        ...data,
        licenseNumber: data.licenses?.[0]?.licenseNumber || "",
        licenseType: data.licenses?.[0]?.licenseType || "",
        licenseIssueDate: data.licenses?.[0]?.issueDate?.slice(0, 10) || "",
        licenseExpiryDate: data.licenses?.[0]?.expiryDate?.slice(0, 10) || "",
        medicalCertificateNumber: data.medicals?.[0]?.medicalCertificateNumber || "",
        medicalIssueDate: data.medicals?.[0]?.issueDate?.slice(0, 10) || "",
        medicalExpiryDate: data.medicals?.[0]?.expiryDate?.slice(0, 10) || "",
        batch: data.batch || "",
        documents: data.documents || []
      }));
    } catch (error) {
      console.error("Failed to load student:", error);
    }
  };

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const validPendingFiles = pendingFiles.filter(pf => pf.file);
    const totalDocs = form.documents.length + validPendingFiles.length;
    
    if (totalDocs < 3) {
      alert("Please ensure at least 3 supporting documents have files actively attached to them before saving.");
      return;
    }

    setIsSubmitting(true);

    const url = isEdit
      ? `http://localhost:3000/api/students/${id}`
      : `http://localhost:3000/api/students`;

    const method = isEdit ? "PUT" : "POST";

    try {
      const formPayload = { ...form };
      delete formPayload.documents; // We handle documents via separate endpoints now

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formPayload)
      });
      const data = await res.json();

      const newStudentId = isEdit ? id : data.id;

      // Upload newly added files seamlessly
      if (validPendingFiles.length > 0) {
        let uploadErrors = 0;
        await Promise.all(validPendingFiles.map(async (pf) => {
          const fd = new FormData();
          fd.append('file', pf.file);
          fd.append('documentType', pf.type || 'General');
          try {
            const upRes = await fetch(`http://localhost:3000/api/students/${newStudentId}/documents`, {
              method: 'POST',
              body: fd
            });
            if (!upRes.ok) {
              uploadErrors++;
              console.error("Failed to upload document", pf.file.name, await upRes.text());
            }
          } catch (err) {
            uploadErrors++;
            console.error("Network error during document upload", err);
          }
        }));

        if (uploadErrors > 0) {
          alert(`Student profile saved, but ${uploadErrors} document(s) failed to upload. Please edit the student to re-upload them.`);
        }
      }

      navigate("/students");
    } catch (error) {
      console.error("Submission failed", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="p-6 md:p-8 max-w-4xl mx-auto min-h-full">
      {/* HEADER */}
      <div className="mb-8">
        <button 
          onClick={() => navigate('/students')}
          className="flex items-center text-sm font-medium text-indigo-600 dark:text-indigo-400 hover:text-indigo-700 mb-4 transition-colors"
        >
          <ChevronLeft size={16} />
          Back to Directory
        </button>
        <h1 className="text-3xl font-bold tracking-tight text-slate-900 dark:text-white">
          {isEdit ? "Edit Student Profile" : "Register Student"}
        </h1>
        <p className="mt-1 text-slate-500 dark:text-slate-400">
          Complete the form below to {isEdit ? "update the" : "create a new"} student record.
        </p>
      </div>

      {/* STEP INDICATOR */}
      <div className="mb-10">
        <div className="flex flex-wrap gap-2 md:gap-0 md:justify-between relative">
          <div className="absolute top-1/2 left-0 w-full h-[2px] bg-slate-100 dark:bg-slate-800 -z-10 hidden md:block rounded-full"></div>
          {steps.map((s, idx) => {
            const Icon = s.icon;
            const isCompleted = step > s.num;
            const isActive = step === s.num;
            return (
              <div key={s.num} className="flex flex-col items-center flex-1 min-w-[80px] z-10">
                <div 
                  className={`w-10 h-10 rounded-full flex items-center justify-center border-4 border-gray-50 dark:border-slate-900 transition-colors duration-300
                    ${isCompleted ? 'bg-emerald-500 text-white' : 
                      isActive ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/40' : 
                      'bg-slate-200 dark:bg-slate-800 text-slate-500 dark:text-slate-400'}
                  `}
                >
                  {isCompleted ? <CheckCircle2 size={18} /> : <Icon size={18} />}
                </div>
                <span className={`text-xs font-semibold mt-2 ${isActive ? 'text-indigo-600 dark:text-indigo-400' : 'text-slate-500 dark:text-slate-400'}`}>
                  {s.title}
                </span>
              </div>
            );
          })}
        </div>
      </div>

      <form onSubmit={handleSubmit} className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-slate-200/60 dark:border-slate-700 overflow-hidden">
        
        {/* FORM CONTENT */}
        <div className="p-6 md:p-8">
          
          {step === 1 && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-6 border-b border-slate-100 dark:border-slate-700 pb-4">Personal Information</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <InputField value={form.firstName} onChange={handleChange} label="First Name" name="firstName" required />
                <InputField value={form.lastName} onChange={handleChange} label="Last Name" name="lastName" required />
                <InputField value={form.email} onChange={handleChange} label="Personal Email" name="email" type="email" required fullWidth />
                <InputField value={form.dob} onChange={handleChange} label="Date of Birth" name="dob" type="date" required />
                <InputField value={form.gender} onChange={handleChange} label="Gender" name="gender" type="select" options={[{value:"Male",label:"Male"},{value:"Female",label:"Female"},{value:"Prefer not to say",label:"Prefer not to say"}]} />
                <InputField value={form.nationality} onChange={handleChange} label="Nationality" name="nationality" />
                <InputField value={form.phone} onChange={handleChange} label="Phone Number" name="phone" />
                <InputField value={form.address} onChange={handleChange} label="Residential Address" name="address" type="textarea" fullWidth />
                <InputField value={form.city} onChange={handleChange} label="City" name="city" />
                <InputField value={form.state} onChange={handleChange} label="State/Province" name="state" />
                <InputField value={form.pincode} onChange={handleChange} label="Pincode / ZIP" name="pincode" />
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
               <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-6 border-b border-slate-100 dark:border-slate-700 pb-4">Aviation License Details</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <InputField value={form.licenseNumber} onChange={handleChange} label="License Number" name="licenseNumber" required fullWidth />
                <InputField value={form.licenseType} onChange={handleChange} label="License Type (e.g. PPL, CPL)" name="licenseType" required fullWidth />
                <InputField value={form.licenseIssueDate} onChange={handleChange} label="Date of Issue" name="licenseIssueDate" type="date" required />
                <InputField value={form.licenseExpiryDate} onChange={handleChange} label="Expiry Date" name="licenseExpiryDate" type="date" required />
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
               <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-6 border-b border-slate-100 dark:border-slate-700 pb-4">Medical Certificate</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <InputField value={form.medicalCertificateNumber} onChange={handleChange} label="Certificate Number" name="medicalCertificateNumber" required fullWidth />
                <InputField value={form.medicalIssueDate} onChange={handleChange} label="Date of Medical Exam" name="medicalIssueDate" type="date" required />
                <InputField value={form.medicalExpiryDate} onChange={handleChange} label="Valid Until" name="medicalExpiryDate" type="date" required />
              </div>
            </div>
          )}

          {step === 4 && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
               <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-6 border-b border-slate-100 dark:border-slate-700 pb-4">School Account Access</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <InputField value={form.schoolEmail} onChange={handleChange} label="School Email Address" name="schoolEmail" type="email" required fullWidth />
                <InputField value={form.passwordHash} onChange={handleChange} label="Temporary Password" name="passwordHash" type="password" required={!isEdit} />
                <InputField 
                  value={form.batch} 
                  onChange={handleChange} 
                  label="Training Batch" 
                  name="batch" 
                  type="select" 
                  required
                  options={[
                    {value: "Ground School", label: "Ground School"},
                    {value: "Simulator", label: "Simulator"},
                    {value: "Dual Flights", label: "Dual Flights"},
                    {value: "Solo Flights", label: "Solo Flights"}
                  ]} 
                />
              </div>
            </div>
          )}

          {step === 5 && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
               <div className="flex justify-between items-center mb-6 border-b border-slate-100 dark:border-slate-700 pb-4">
                  <h2 className="text-xl font-bold text-slate-900 dark:text-white">Supporting Documents</h2>
                  <button 
                    type="button" 
                    onClick={() => setPendingFiles(prev => [...prev, { file: null, type: "" }])}
                    className="flex items-center gap-1.5 px-4 py-2 bg-indigo-50 dark:bg-indigo-500/10 text-indigo-700 dark:text-indigo-400 text-sm font-semibold rounded-xl hover:bg-indigo-100 dark:hover:bg-indigo-500/20 transition-colors"
                  >
                    <Plus size={16} /> Add Document
                  </button>
               </div>
              
              {/* Existing Documents */}
              {form.documents.length > 0 && (
                <div className="mb-6 space-y-3">
                  <h3 className="text-sm font-semibold text-slate-500 uppercase tracking-wider">Already Uploaded</h3>
                  {form.documents.map((doc, index) => (
                    <div key={index} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-200 dark:bg-slate-900 dark:border-slate-700 rounded-xl hover:shadow-sm transition-all duration-200 group">
                      <div className="flex items-center gap-3">
                        <FileText className="text-indigo-500" size={24} />
                        <div>
                          <p className="text-sm font-semibold text-slate-900 dark:text-white">{doc.documentType || 'Document'} <span className="text-xs font-normal text-slate-500 ml-2">Stored File</span></p>
                          <a href={doc.fileUrl.startsWith('http') ? doc.fileUrl : `http://localhost:3000${doc.fileUrl}`} target="_blank" rel="noreferrer" className="text-xs font-medium text-indigo-600 hover:text-indigo-700 dark:text-indigo-400 group-hover:underline">View Original File</a>
                        </div>
                      </div>
                      {isEdit && (
                        <button 
                          type="button" 
                          onClick={async () => {
                            if (!window.confirm("Permanently delete this document?")) return;
                            try {
                              await fetch(`http://localhost:3000/api/students/${id}/documents/${doc.id}`, { method: 'DELETE' });
                              setForm(prev => ({ ...prev, documents: prev.documents.filter(d => d.id !== doc.id) }));
                            } catch (e) {
                              console.error(e);
                            }
                          }}
                          className="p-2 text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/10 rounded-lg opacity-60 group-hover:opacity-100 transition-all"
                          title="Delete Stored Document"
                        >
                          <Trash2 size={18} />
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              )}

              {/* Pending Files List (Slots) */}
              {pendingFiles.length > 0 && (
                <div className="mt-6 space-y-4">
                  <h3 className="text-sm font-semibold text-slate-500 uppercase tracking-wider">New Documents</h3>
                  {pendingFiles.map((pf, idx) => (
                    <div key={idx} className="p-4 bg-indigo-50/30 border border-indigo-100 dark:bg-indigo-900/10 dark:border-indigo-800/50 rounded-xl space-y-4 relative">
                      
                      <button 
                        type="button" 
                        onClick={() => setPendingFiles(prev => prev.filter((_, i) => i !== idx))}
                        className="absolute top-4 right-4 p-1.5 text-rose-500 hover:bg-rose-100 dark:hover:bg-rose-900/30 rounded-lg transition-colors"
                      >
                        <Trash2 size={18} />
                      </button>

                      <div>
                        <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Document Type / Name</label>
                        <input
                          type="text"
                          placeholder="e.g. ID Proof, Passport"
                          value={pf.type}
                          onChange={(e) => {
                            const updated = [...pendingFiles];
                            updated[idx].type = e.target.value;
                            setPendingFiles(updated);
                          }}
                          className="w-full pr-12 px-4 py-2 text-sm border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500"
                        />
                      </div>

                      <div>
                        <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Attach File</label>
                        {pf.file ? (
                          <div className="flex items-center justify-between p-3 bg-white border border-slate-200 dark:bg-slate-900 dark:border-slate-700 rounded-lg">
                            <div className="flex items-center gap-3 overflow-hidden">
                              <FileText className="text-indigo-500 shrink-0" size={20} />
                              <div className="truncate">
                                <p className="text-sm font-medium text-slate-900 dark:text-white truncate">{pf.file.name}</p>
                                <p className="text-xs text-slate-500">{(pf.file.size / 1024 / 1024).toFixed(2)} MB</p>
                              </div>
                            </div>
                            <button 
                              type="button" 
                              onClick={() => {
                                const updated = [...pendingFiles];
                                updated[idx].file = null;
                                setPendingFiles(updated);
                              }}
                              className="text-xs font-medium text-indigo-600 hover:text-indigo-700 bg-indigo-50 py-1.5 px-3 rounded-md transition-colors"
                            >
                              Change
                            </button>
                          </div>
                        ) : (
                          <div 
                            className="relative flex items-center justify-center p-6 border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-lg bg-slate-50 dark:bg-slate-800/50 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 hover:border-indigo-400 transition-colors cursor-pointer group"
                          >
                            <input
                              type="file"
                              accept=".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx"
                              onChange={(e) => {
                                const file = e.target.files[0];
                                if (file) {
                                  const updated = [...pendingFiles];
                                  updated[idx].file = file;
                                  setPendingFiles(updated);
                                }
                              }}
                              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                            />
                            <div className="flex flex-col items-center pointer-events-none">
                              <Upload className="text-slate-400 group-hover:text-indigo-500 mb-2 transition-colors" size={24} />
                              <p className="text-sm font-semibold text-slate-600 dark:text-slate-300">Click to browse or drag & drop</p>
                            </div>
                          </div>
                        )}
                      </div>

                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {/* NAVIGATION FOOTER */}
        <div className="bg-slate-50/80 dark:bg-slate-800/80 px-6 md:px-8 py-5 border-t border-slate-200/60 dark:border-slate-700 flex items-center justify-between">
          <div>
            {step > 1 && (
              <button
                type="button"
                onClick={(e) => { e.preventDefault(); setStep(s => s - 1); }}
                className="flex items-center gap-2 px-5 py-2.5 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 text-slate-700 dark:text-slate-300 font-semibold rounded-xl hover:bg-slate-50 dark:hover:bg-slate-600 transition-colors shadow-sm"
              >
                <ChevronLeft size={18} /> Back
              </button>
            )}
          </div>

          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => navigate("/students")}
              className="px-5 py-2.5 text-slate-500 dark:text-slate-400 font-semibold hover:text-slate-700 dark:hover:text-slate-300 transition-colors"
            >
              Cancel
            </button>

            {step < 5 ? (
              <button
                type="button"
                onClick={(e) => { 
                  e.preventDefault(); 
                  const formElement = e.target.closest('form');
                  if (formElement && !formElement.reportValidity()) return;
                  setStep(s => s + 1); 
                }}
                className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 text-white font-semibold rounded-xl hover:bg-indigo-700 transition-colors shadow-sm shadow-indigo-500/20"
              >
                Next Step <ChevronRight size={18} />
              </button>
            ) : (
              <button
                type="submit"
                disabled={isSubmitting}
                className="flex items-center gap-2 px-6 py-2.5 bg-emerald-600 text-white font-bold rounded-xl hover:bg-emerald-700 transition-all shadow-md shadow-emerald-500/20 disabled:opacity-70 disabled:cursor-wait"
              >
                {isSubmitting ? (
                  <span className="flex items-center gap-2">Processing...</span>
                ) : (
                  <><Save size={18} /> Save Student</>
                )}
              </button>
            )}
          </div>
        </div>
      </form>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import {
  ChevronLeft, Edit2, User, ShieldCheck, HeartPulse,
  Lock, FileText, MapPin, Phone, Mail, Calendar,
  Globe, CreditCard, BookOpen, ExternalLink, Badge
} from "lucide-react";

export default function StudentProfile() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [student, setStudent] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStudent();
  }, [id]);

  const fetchStudent = async () => {
    try {
      const res = await fetch(`http://localhost:3000/api/students/${id}`);
      const data = await res.json();
      setStudent(data);
    } catch (err) {
      console.error("Failed to load student:", err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="flex flex-col items-center gap-3">
          <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin" />
          <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">Loading student profile...</p>
        </div>
      </div>
    );
  }

  if (!student) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <p className="text-slate-500">Student not found.</p>
      </div>
    );
  }

  const license = student.licenses?.[0];
  const medical = student.medicals?.[0];
  const account = student.account;
  const documents = student.documents || [];

  const formatDate = (dateStr) => {
    if (!dateStr) return "—";
    return new Date(dateStr).toLocaleDateString("en-GB", {
      day: "2-digit", month: "short", year: "numeric"
    });
  };

  const isExpired = (dateStr) => {
    if (!dateStr) return false;
    return new Date(dateStr) < new Date();
  };

  const expiringSoon = (dateStr) => {
    if (!dateStr) return false;
    const diff = (new Date(dateStr) - new Date()) / (1000 * 60 * 60 * 24);
    return diff >= 0 && diff < 30;
  };

  const DateBadge = ({ date }) => {
    if (!date) return <span className="text-slate-400">—</span>;
    if (isExpired(date)) return <span className="text-rose-600 font-semibold">{formatDate(date)} · Expired</span>;
    if (expiringSoon(date)) return <span className="text-amber-600 font-semibold">{formatDate(date)} · Expiring Soon</span>;
    return <span className="text-slate-800 dark:text-slate-200">{formatDate(date)}</span>;
  };

  return (
    <div className="p-6 md:p-8 max-w-5xl mx-auto min-h-full">

      {/* BACK + HEADER */}
      <div className="mb-8">
        <button
          onClick={() => navigate("/students")}
          className="flex items-center gap-1.5 text-sm font-medium text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 mb-4 transition-colors"
        >
          <ChevronLeft size={16} /> Back to Directory
        </button>

        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-5">
            <div className="w-20 h-20 rounded-3xl bg-gradient-to-br from-indigo-500 to-blue-600 flex items-center justify-center text-white text-3xl font-bold shadow-lg shadow-indigo-500/30">
              {student.firstName?.[0]}{student.lastName?.[0]}
            </div>
            <div>
              <h1 className="text-3xl font-bold text-slate-900 dark:text-white">
                {student.firstName} {student.lastName}
              </h1>
              <p className="text-slate-500 dark:text-slate-400 font-mono text-sm mt-1">{student.studentId}</p>
              <div className="flex items-center gap-2 mt-2">
                {license
                  ? <span className="px-2.5 py-0.5 text-xs font-semibold rounded-full bg-indigo-50 text-indigo-700 border border-indigo-200 dark:bg-indigo-500/10 dark:text-indigo-400 dark:border-indigo-500/20">License Active</span>
                  : <span className="px-2.5 py-0.5 text-xs font-semibold rounded-full bg-rose-50 text-rose-700 border border-rose-200 dark:bg-rose-500/10 dark:text-rose-400 dark:border-rose-500/20">No License</span>
                }
                {medical
                  ? <span className="px-2.5 py-0.5 text-xs font-semibold rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20">Medical Valid</span>
                  : <span className="px-2.5 py-0.5 text-xs font-semibold rounded-full bg-rose-50 text-rose-700 border border-rose-200 dark:bg-rose-500/10 dark:text-rose-400 dark:border-rose-500/20">No Medical</span>
                }
              </div>
            </div>
          </div>

          <button
            onClick={() => navigate(`/students/edit/${student.id}`)}
            className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold rounded-xl shadow-md shadow-indigo-500/20 transition-all hover:-translate-y-0.5"
          >
            <Edit2 size={16} /> Edit Profile
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* PERSONAL INFO */}
        <SectionCard icon={<User size={20} className="text-indigo-500" />} title="Personal Information">
          <InfoRow icon={<Mail size={15} />} label="Personal Email" value={student.email} />
          <InfoRow icon={<Calendar size={15} />} label="Date of Birth" value={formatDate(student.dob)} />
          <InfoRow icon={<Badge size={15} />} label="Gender" value={student.gender} />
          <InfoRow icon={<Globe size={15} />} label="Nationality" value={student.nationality} />
          <InfoRow icon={<Phone size={15} />} label="Phone" value={student.phone} />
        </SectionCard>

        {/* ADDRESS */}
        <SectionCard icon={<MapPin size={20} className="text-rose-500" />} title="Address">
          <InfoRow label="Address" value={student.address} full />
          <InfoRow label="City" value={student.city} />
          <InfoRow label="State / Province" value={student.state} />
          <InfoRow label="Pincode / ZIP" value={student.pincode} />
        </SectionCard>

        {/* LICENSE */}
        <SectionCard icon={<ShieldCheck size={20} className="text-blue-500" />} title="Aviation License">
          {license ? (
            <>
              <InfoRow icon={<CreditCard size={15} />} label="License Number" value={license.licenseNumber} />
              <InfoRow icon={<BookOpen size={15} />} label="License Type" value={license.licenseType} />
              <InfoRow icon={<Calendar size={15} />} label="Issue Date" value={formatDate(license.issueDate)} />
              <div className="grid grid-cols-[1fr_auto_2fr] gap-x-3 items-start py-2.5 border-b border-slate-50 dark:border-slate-700/50 last:border-0">
                <span className="text-xs font-semibold text-slate-400 uppercase tracking-wide pt-0.5">Expiry Date</span>
                <span className="text-slate-200 dark:text-slate-600">·</span>
                <DateBadge date={license.expiryDate} />
              </div>
            </>
          ) : (
            <EmptySection text="No license on record" />
          )}
        </SectionCard>

        {/* MEDICAL */}
        <SectionCard icon={<HeartPulse size={20} className="text-emerald-500" />} title="Medical Certificate">
          {medical ? (
            <>
              <InfoRow icon={<CreditCard size={15} />} label="Certificate No." value={medical.medicalCertificateNumber} />
              <InfoRow icon={<Calendar size={15} />} label="Issue Date" value={formatDate(medical.issueDate)} />
              <div className="grid grid-cols-[1fr_auto_2fr] gap-x-3 items-start py-2.5 border-b border-slate-50 dark:border-slate-700/50 last:border-0">
                <span className="text-xs font-semibold text-slate-400 uppercase tracking-wide pt-0.5">Valid Until</span>
                <span className="text-slate-200 dark:text-slate-600">·</span>
                <DateBadge date={medical.expiryDate} />
              </div>
            </>
          ) : (
            <EmptySection text="No medical certificate on record" />
          )}
        </SectionCard>

        {/* ACCOUNT */}
        <SectionCard icon={<Lock size={20} className="text-amber-500" />} title="School Account">
          {account ? (
            <InfoRow icon={<Mail size={15} />} label="School Email" value={account.schoolEmail} />
          ) : (
            <EmptySection text="No school account created" />
          )}
        </SectionCard>

        {/* DOCUMENTS */}
        <SectionCard icon={<FileText size={20} className="text-purple-500" />} title={`Documents (${documents.length})`}>
          {documents.length > 0 ? (
            <div className="space-y-3">
              {documents.map((doc, i) => (
                <div key={i} className="flex items-center justify-between gap-3 p-3 rounded-xl bg-slate-50 dark:bg-slate-900/50 border border-slate-100 dark:border-slate-700/60">
                  <div>
                    <p className="text-sm font-semibold text-slate-800 dark:text-slate-200">{doc.documentType || "Unnamed Document"}</p>
                    <p className="text-xs text-slate-400 mt-0.5 truncate max-w-[220px]">{doc.fileUrl || "No URL"}</p>
                  </div>
                  {doc.fileUrl && (
                    <a
                      href={doc.fileUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="p-2 rounded-lg text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-500/10 transition-colors flex-shrink-0"
                      title="Open Document"
                    >
                      <ExternalLink size={16} />
                    </a>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <EmptySection text="No documents attached" />
          )}
        </SectionCard>

      </div>
    </div>
  );
}

function SectionCard({ icon, title, children }) {
  return (
    <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-slate-200/60 dark:border-slate-700 overflow-hidden">
      <div className="flex items-center gap-3 px-6 py-4 border-b border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/50">
        {icon}
        <h3 className="font-bold text-slate-800 dark:text-white text-sm">{title}</h3>
      </div>
      <div className="px-6 py-5 divide-y divide-slate-50 dark:divide-slate-700/50">
        {children}
      </div>
    </div>
  );
}

function InfoRow({ icon, label, value, full }) {
  return (
    <div className={`${full ? 'flex flex-col gap-1' : 'grid grid-cols-[1fr_auto_2fr] gap-x-3 items-start'} py-2.5 border-b border-slate-50 dark:border-slate-700/50 last:border-0`}>
      <div className="flex items-center gap-1.5 text-xs font-semibold text-slate-400 uppercase tracking-wide pt-0.5">
        {icon && <span className="text-slate-300 dark:text-slate-600">{icon}</span>}
        {label}
      </div>
      {!full && <span className="text-slate-200 dark:text-slate-600">·</span>}
      <span className="text-sm text-slate-800 dark:text-slate-200 break-words">{value || "—"}</span>
    </div>
  );
}

function EmptySection({ text }) {
  return (
    <div className="py-4 text-center text-sm text-slate-400 italic">{text}</div>
  );
}

